// ============================================================
// Worker واحد يجمع كل نقاط الـ API + يخدّم الملفات الثابتة (index.html)
// هذا البديل عن مجلد functions/ لأن أداة الرفع السريع بالجوال لا تدعم
// اصطلاح "Pages Functions". يحتاج ربط KV namespace باسم SCHOOL_KV.
// ============================================================

const DATA_KEY = "school-data";

function defaultData() {
  return {
    settings: {
      schoolName: "مدرسة أبوداوود الابتدائية",
      adminPasswordHash: null,
      teacherPasswordHash: null,
      lastRaffle: null,
      nafesMasteryThreshold: 80, // الحد الأدنى للدرجة لاعتبار الطالب في مرحلة الإتقان (قابل للتعديل من الإعدادات)
      grades: [
        "الأول الابتدائي",
        "الثاني الابتدائي",
        "الثالث الابتدائي",
        "الرابع الابتدائي",
        "الخامس الابتدائي",
        "السادس الابتدائي",
      ],
      sections: ["أ", "ب", "ج", "د", "هـ"],
      pointValues: [5, 10, 15, 20],
      reasons: [
        { id: "discipline", label: "الانضباط والالتزام بالنظام", points: 5 },
        { id: "uniform", label: "الالتزام بالزي المدرسي والمظهر", points: 5 },
        { id: "participation", label: "المشاركة الصفية الإيجابية", points: 10 },
        { id: "memorization", label: "التسميع أو الحفظ المتميز", points: 10 },
        { id: "homework", label: "التفوق الدراسي وأداء الواجبات", points: 10 },
        { id: "honesty", label: "الأمانة (مثل إعادة شيء مفقود)", points: 15 },
        { id: "anti_bullying", label: "الالتزام بالبعد عن التنمر وإيذاء الآخرين", points: 15 },
        { id: "good_conduct", label: "السلوك الحسن مع الزملاء والمعلمين", points: 15 },
        { id: "volunteering", label: "المبادرة والتطوع لخدمة الفصل أو المدرسة", points: 20 },
        { id: "excellence", label: "تميّز استثنائي (مسابقة أو إنجاز بارز)", points: 20 },
        { id: "nafes_participation", label: "مشاركة الطالب بالحل في منصة نافس", points: 5 },
        { id: "nafes_mastery", label: "وصول الطالب لمرحلة الإتقان في منصة نافس", points: 10 },
        { id: "activities_participation", label: "المشاركة في منصة الأنشطة والفعاليات", points: 10 },
      ],
    },
    students: [],
    trash: [],
  };
}

async function loadData(env) {
  const raw = await env.SCHOOL_KV.get(DATA_KEY);
  if (!raw) {
    const fresh = defaultData();
    await env.SCHOOL_KV.put(DATA_KEY, JSON.stringify(fresh));
    return fresh;
  }
  try {
    const parsed = JSON.parse(raw);
    const def = defaultData();
    parsed.settings = { ...def.settings, ...(parsed.settings || {}) };
    parsed.students = parsed.students || [];
    parsed.trash = parsed.trash || [];
    return parsed;
  } catch {
    const fresh = defaultData();
    await env.SCHOOL_KV.put(DATA_KEY, JSON.stringify(fresh));
    return fresh;
  }
}

async function saveData(env, data) {
  await env.SCHOOL_KV.put(DATA_KEY, JSON.stringify(data));
}

function json(body, init = {}) {
  return new Response(JSON.stringify(body), {
    status: init.status || 200,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Headers": "Content-Type, x-admin-password",
      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    },
  });
}

async function sha256(text) {
  const enc = new TextEncoder().encode(text);
  const buf = await crypto.subtle.digest("SHA-256", enc);
  return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
}

async function requireAuth(request, data) {
  const pass = request.headers.get("x-admin-password") || "";
  if (!data.settings.adminPasswordHash) return { ok: false, reason: "not-setup" };
  const hash = await sha256(pass);
  if (hash === data.settings.adminPasswordHash) return { ok: true, role: "admin" };
  if (data.settings.teacherPasswordHash && hash === data.settings.teacherPasswordHash) return { ok: true, role: "teacher" };
  return { ok: false, reason: "wrong-password" };
}

async function requireAdmin(request, data) {
  const auth = await requireAuth(request, data);
  if (!auth.ok || auth.role !== "admin") return { ok: false, reason: auth.reason || "not-admin" };
  return { ok: true };
}

function onlyDigits(str) {
  return (str || "").toString().replace(/[^0-9]/g, "");
}

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

async function readJson(request) {
  return await request.json().catch(() => ({}));
}

// ============================================================
// المعالِجات (handlers)
// ============================================================

async function handleStudent(request, env) {
  const url = new URL(request.url);
  const nationalId = onlyDigits(url.searchParams.get("id"));
  if (!nationalId) return json({ error: "أدخل رقم الهوية." }, { status: 400 });

  const data = await loadData(env);
  const student = data.students.find((s) => s.nationalId === nationalId);
  if (!student) return json({ error: "لم يتم العثور على طالب بهذا الرقم." }, { status: 404 });

  return json({
    name: student.name,
    grade: student.grade,
    section: student.section,
    balance: student.balance,
    history: (student.history || []).slice(-15).reverse(),
  });
}

async function handleLeaderboard(env) {
  const data = await loadData(env);
  const top = [...data.students]
    .sort((a, b) => (b.balance || 0) - (a.balance || 0))
    .slice(0, 10)
    .map((s) => ({ name: s.name, grade: s.grade, section: s.section, balance: s.balance || 0 }));
  return json({ schoolName: data.settings.schoolName, top, lastRaffle: data.settings.lastRaffle || null });
}

async function handleAdminSetup(request, env) {
  const body = await readJson(request);
  const password = (body.password || "").toString();
  if (password.length < 4) return json({ error: "كلمة المرور قصيرة جدًا (٤ أحرف على الأقل)." }, { status: 400 });

  const data = await loadData(env);
  if (data.settings.adminPasswordHash) {
    return json({ error: "تم ضبط كلمة المرور مسبقًا. استخدم تغيير كلمة المرور من الإعدادات." }, { status: 409 });
  }
  data.settings.adminPasswordHash = await sha256(password);
  await saveData(env, data);
  return json({ ok: true });
}

async function handleAdminLogin(request, env) {
  const body = await readJson(request);
  const password = (body.password || "").toString();
  const data = await loadData(env);

  if (!data.settings.adminPasswordHash) return json({ needsSetup: true });

  const hash = await sha256(password);
  if (hash === data.settings.adminPasswordHash) {
    return json({ ok: true, role: "admin", schoolName: data.settings.schoolName });
  }
  if (data.settings.teacherPasswordHash && hash === data.settings.teacherPasswordHash) {
    return json({ ok: true, role: "teacher", schoolName: data.settings.schoolName });
  }
  return json({ error: "كلمة المرور غير صحيحة." }, { status: 401 });
}

async function handleChangePassword(request, env) {
  const data = await loadData(env);
  const auth = await requireAdmin(request, data);
  if (!auth.ok) return json({ error: "كلمة المرور الحالية غير صحيحة." }, { status: 401 });

  const body = await readJson(request);
  const newPassword = (body.newPassword || "").toString();
  if (newPassword.length < 4) return json({ error: "كلمة المرور الجديدة قصيرة جدًا (٤ أحرف على الأقل)." }, { status: 400 });

  data.settings.adminPasswordHash = await sha256(newPassword);
  await saveData(env, data);
  return json({ ok: true });
}

async function handleTeacherPassword(request, env) {
  const data = await loadData(env);
  const auth = await requireAdmin(request, data);
  if (!auth.ok) return json({ error: "غير مصرح. هذه العملية للمشرف الكامل فقط." }, { status: 401 });

  const body = await readJson(request);
  const password = (body.password || "").toString();
  if (password.length < 4) return json({ error: "كلمة المرور قصيرة جدًا (٤ أحرف على الأقل)." }, { status: 400 });

  data.settings.teacherPasswordHash = await sha256(password);
  await saveData(env, data);
  return json({ ok: true });
}

// نسخة خفيفة من قائمة الطلاب (اسم/صف/فصل/رقم هوية فقط، بدون رصيد أو سجل)
// للمشرف والمعلم معًا — تُستخدم لاختيار الطلاب في صفحات "نافس" و"الأنشطة والفعاليات"
async function handleStudentsLite(request, env) {
  const data = await loadData(env);
  const auth = await requireAuth(request, data);
  if (!auth.ok) return json({ error: "غير مصرح." }, { status: 401 });

  const students = data.students.map((s) => ({
    id: s.id,
    nationalId: s.nationalId,
    name: s.name,
    grade: s.grade,
    section: s.section,
  }));
  return json({
    students,
    grades: data.settings.grades,
    sections: data.settings.sections,
    nafesMasteryThreshold: data.settings.nafesMasteryThreshold,
  });
}

async function handleAdminDataGet(request, env) {
  const data = await loadData(env);
  const auth = await requireAuth(request, data);
  if (!auth.ok) return json({ error: "غير مصرح." }, { status: 401 });

  if (auth.role === "teacher") {
    return json({ settings: data.settings, students: [], trash: [], role: "teacher" });
  }
  return json({ ...data, role: "admin" });
}

async function handleAdminDataPost(request, env) {
  const current = await loadData(env);
  const auth = await requireAdmin(request, current);
  if (!auth.ok) return json({ error: "غير مصرح." }, { status: 401 });

  const body = await readJson(request);
  if (!body || !Array.isArray(body.students)) return json({ error: "بيانات غير صالحة." }, { status: 400 });

  const next = {
    settings: {
      ...current.settings,
      ...(body.settings || {}),
      adminPasswordHash: current.settings.adminPasswordHash,
      teacherPasswordHash: current.settings.teacherPasswordHash,
    },
    students: body.students,
    trash: Array.isArray(body.trash) ? body.trash : current.trash,
  };
  await saveData(env, next);
  return json({ ok: true });
}

async function handlePoints(request, env) {
  const data = await loadData(env);
  const auth = await requireAuth(request, data);
  if (!auth.ok) return json({ error: "غير مصرح." }, { status: 401 });

  const body = await readJson(request);
  const nationalId = onlyDigits(body.nationalId);
  const points = Number(body.points);
  const reasonId = (body.reasonId || "").toString();
  const adminName = (body.adminName || "").toString().trim() || "مشرف";

  if (!nationalId) return json({ error: "أدخل رقم هوية الطالب." }, { status: 400 });
  if (!data.settings.pointValues.includes(points)) return json({ error: "قيمة نقاط غير صالحة." }, { status: 400 });
  const reason = data.settings.reasons.find((r) => r.id === reasonId);
  if (!reason) return json({ error: "سبب الإضافة غير معروف." }, { status: 400 });

  const student = data.students.find((s) => s.nationalId === nationalId);
  if (!student) return json({ error: "لم يتم العثور على طالب بهذا الرقم." }, { status: 404 });

  student.balance = (student.balance || 0) + points;
  student.history = student.history || [];
  student.history.push({ date: new Date().toISOString(), points, reason: reason.label, adminName, by: auth.role });

  await saveData(env, data);
  return json({ ok: true, name: student.name, newBalance: student.balance });
}

async function handleBulkPoints(request, env) {
  const data = await loadData(env);
  const auth = await requireAuth(request, data);
  if (!auth.ok) return json({ error: "غير مصرح." }, { status: 401 });

  const body = await readJson(request);
  const ids = Array.isArray(body.ids) ? body.ids.map(onlyDigits).filter(Boolean) : [];
  const points = Number(body.points);
  const reasonId = (body.reasonId || "").toString();
  const adminName = (body.adminName || "").toString().trim() || "مشرف";

  if (!ids.length) return json({ error: "لم يتم العثور على أي أرقام هوية صالحة بالملف." }, { status: 400 });
  if (!data.settings.pointValues.includes(points)) return json({ error: "قيمة نقاط غير صالحة." }, { status: 400 });
  const reason = data.settings.reasons.find((r) => r.id === reasonId);
  if (!reason) return json({ error: "سبب الإضافة غير معروف." }, { status: 400 });

  const uniqueIds = [...new Set(ids)];
  const notFound = [];
  let successCount = 0;
  const now = new Date().toISOString();

  for (const nationalId of uniqueIds) {
    const student = data.students.find((s) => s.nationalId === nationalId);
    if (!student) { notFound.push(nationalId); continue; }
    student.balance = (student.balance || 0) + points;
    student.history = student.history || [];
    student.history.push({ date: now, points, reason: reason.label, adminName, by: auth.role, bulk: true });
    successCount++;
  }

  await saveData(env, data);
  return json({ ok: true, successCount, totalRequested: uniqueIds.length, notFound });
}

async function handleRaffle(request, env) {
  const data = await loadData(env);
  const auth = await requireAdmin(request, data);
  if (!auth.ok) return json({ error: "غير مصرح." }, { status: 401 });

  const body = await readJson(request);
  const mode = (body.mode || "all").toString();
  const grade = (body.grade || "").toString();
  const section = (body.section || "").toString();
  const count = Math.max(1, Math.min(20, Number(body.count) || 1));
  const label = (body.label || "").toString().trim();
  const publish = !!body.publish;

  let pool = data.students;
  if (mode === "grade" && grade) pool = pool.filter((s) => s.grade === grade);
  if (mode === "section" && section) pool = pool.filter((s) => s.section === section);
  if (mode === "top") pool = [...pool].sort((a, b) => (b.balance || 0) - (a.balance || 0)).slice(0, 20);

  if (!pool.length) return json({ error: "لا يوجد طلاب مطابقين لشروط القرعة." }, { status: 400 });

  const winners = shuffle(pool).slice(0, count).map((s) => ({ name: s.name, grade: s.grade, section: s.section, balance: s.balance || 0 }));

  if (publish) {
    data.settings.lastRaffle = { date: new Date().toISOString(), mode, label: label || "قرعة الفائزين", winners };
    await saveData(env, data);
  }

  return json({ ok: true, winners });
}

// ============================================================
// التوجيه (router)
// ============================================================

const ROUTES = {
  "GET /api/student": (req, env) => handleStudent(req, env),
  "GET /api/leaderboard": (req, env) => handleLeaderboard(env),
  "POST /api/admin/setup": (req, env) => handleAdminSetup(req, env),
  "POST /api/admin/login": (req, env) => handleAdminLogin(req, env),
  "POST /api/admin/change-password": (req, env) => handleChangePassword(req, env),
  "POST /api/admin/teacher-password": (req, env) => handleTeacherPassword(req, env),
  "GET /api/admin/students-lite": (req, env) => handleStudentsLite(req, env),
  "GET /api/admin/data": (req, env) => handleAdminDataGet(req, env),
  "POST /api/admin/data": (req, env) => handleAdminDataPost(req, env),
  "POST /api/admin/points": (req, env) => handlePoints(req, env),
  "POST /api/admin/bulk-points": (req, env) => handleBulkPoints(req, env),
  "POST /api/admin/raffle": (req, env) => handleRaffle(req, env),
};

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (request.method === "OPTIONS" && url.pathname.startsWith("/api/")) {
      return json({ ok: true });
    }

    if (url.pathname.startsWith("/api/")) {
      const key = `${request.method} ${url.pathname}`;
      const handler = ROUTES[key];
      if (handler) {
        try {
          return await handler(request, env);
        } catch (err) {
          return json({ error: "حدث خطأ غير متوقع بالسيرفر." }, { status: 500 });
        }
      }
      return json({ error: "المسار غير موجود." }, { status: 404 });
    }

    // أي طلب غير /api/* نرجّع له صفحة الواجهة المضمّنة مباشرة بالملف (SPA بملف واحد)
    return new Response(HTML_PAGE, {
      status: 200,
      headers: { "Content-Type": "text/html; charset=utf-8" },
    });
  },
};

const HTML_PAGE = "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\" />\n<title>\u0631\u0635\u064a\u062f \u0627\u0644\u0627\u0646\u0636\u0628\u0627\u0637 \u2014 \u0645\u062f\u0631\u0633\u0629 \u0623\u0628\u0648\u062f\u0627\u0648\u0648\u062f \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Tajawal:wght@400;500;700;900&display=swap\" rel=\"stylesheet\">\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js\"></script>\n<style>\n  :root{\n    --navy:#123b50;\n    --navy-dark:#0c2a3a;\n    --green:#1c714d;\n    --gold:#d6a62e;\n    --gold-light:#f3e6bf;\n    --bg:#f5f8f7;\n    --card:#FFFFFF;\n    --ink:#1D2733;\n    --muted:#6B7A8A;\n    --danger:#B3452E;\n    --ok:#2F7A4F;\n    --radius:14px;\n    --shadow:0 2px 10px rgba(18,59,80,0.08);\n  }\n  *{box-sizing:border-box}\n  html,body{margin:0;padding:0;background:var(--bg);color:var(--ink);font-family:'Tajawal',Tahoma,Arial,sans-serif;}\n  body{padding-bottom:40px;}\n  header.top{\n    background:linear-gradient(135deg,var(--navy),var(--navy-dark));\n    color:#fff;padding:18px 16px 14px;\n    display:flex;align-items:center;justify-content:space-between;gap:12px;\n    position:sticky;top:0;z-index:20;\n    box-shadow:var(--shadow);\n  }\n  header.top .brand{display:flex;flex-direction:column;gap:2px;}\n  header.top .brand b{font-size:19px;font-weight:900;}\n  header.top .brand span{font-size:12px;color:var(--gold-light);}\n  nav.tabs{\n    display:flex;gap:8px;padding:10px 12px;background:var(--navy);\n    overflow-x:auto;position:sticky;top:64px;z-index:19;\n  }\n  nav.tabs button{\n    border:none;background:rgba(255,255,255,0.08);color:#fff;\n    padding:9px 16px;border-radius:999px;font-family:inherit;font-size:14px;font-weight:700;\n    white-space:nowrap;cursor:pointer;transition:.15s;\n  }\n  nav.tabs button.active{background:var(--gold);color:var(--navy-dark);}\n  main{max-width:780px;margin:0 auto;padding:18px 14px;}\n  .card{background:var(--card);border-radius:var(--radius);box-shadow:var(--shadow);padding:20px;margin-bottom:16px;}\n  h2{margin:0 0 6px;font-size:20px;color:var(--green);}\n  .logo-header{width:52px;height:52px;object-fit:contain;border-radius:10px;background:#fff;flex-shrink:0;}\n  .announcement-img{width:100%;display:block;border-radius:16px;box-shadow:0 6px 24px rgba(18,59,80,0.12);cursor:zoom-in;}\n  .points-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;}\n  .points-grid .item{border:1px solid #e1ebe7;border-radius:14px;padding:14px;text-align:center;background:#fbfdfc;line-height:1.7;font-size:13px;}\n  .points-grid .item b{display:block;color:var(--green);margin-bottom:5px;font-size:13.5px;}\n  .hero-title{font-size:24px;font-weight:900;color:var(--navy);margin:0 0 6px;text-align:center;}\n  .hero-tag{text-align:center;color:var(--muted);font-size:14px;margin:0 0 6px;line-height:1.8;}\n  p.hint{color:var(--muted);font-size:13.5px;margin:0 0 16px;line-height:1.7;}\n  label{display:block;font-size:13.5px;font-weight:700;margin-bottom:6px;color:var(--navy);}\n  input,select{\n    width:100%;padding:11px 12px;border:1.5px solid #E2E6EA;border-radius:10px;\n    font-family:inherit;font-size:15px;margin-bottom:14px;background:#fff;color:var(--ink);\n  }\n  input:focus,select:focus{outline:none;border-color:var(--gold);}\n  button.btn{\n    border:none;background:var(--navy);color:#fff;padding:12px 18px;border-radius:10px;\n    font-family:inherit;font-size:15px;font-weight:700;cursor:pointer;width:100%;transition:.15s;\n  }\n  button.btn:hover{background:var(--navy-dark);}\n  button.btn.gold{background:var(--gold);color:var(--navy-dark);}\n  button.btn.ghost{background:#EEF2F5;color:var(--navy);}\n  button.btn.danger{background:#F6E4DF;color:var(--danger);}\n  button.btn.sm{width:auto;padding:8px 14px;font-size:13.5px;}\n  .row{display:flex;gap:10px;}\n  .row > *{flex:1;}\n  .balance-hero{\n    text-align:center;padding:26px 10px;background:linear-gradient(135deg,var(--navy),var(--navy-dark));\n    border-radius:var(--radius);color:#fff;margin-bottom:16px;\n  }\n  .balance-hero .num{font-size:46px;font-weight:900;color:var(--gold);}\n  .balance-hero .label{font-size:14px;color:#CBD7E2;margin-top:4px;}\n  .student-meta{display:flex;justify-content:center;gap:18px;margin-top:10px;font-size:13.5px;color:#CBD7E2;}\n  table{width:100%;border-collapse:collapse;font-size:13.5px;}\n  th,td{padding:9px 8px;text-align:right;border-bottom:1px solid #EEF1F4;}\n  th{color:var(--muted);font-weight:700;font-size:12.5px;}\n  .pill{display:inline-block;padding:3px 10px;border-radius:999px;background:var(--gold-light);color:#7A5A16;font-size:12px;font-weight:700;}\n  .empty{text-align:center;color:var(--muted);padding:30px 10px;font-size:14px;}\n  .msg{padding:12px 14px;border-radius:10px;margin-bottom:14px;font-size:14px;font-weight:600;}\n  .msg.ok{background:#E7F4EC;color:var(--ok);}\n  .msg.err{background:#FAE8E3;color:var(--danger);}\n  .point-choices{display:flex;gap:8px;margin-bottom:14px;flex-wrap:wrap;}\n  .point-choices button{\n    flex:1;min-width:60px;padding:10px 6px;border-radius:10px;border:2px solid #E2E6EA;\n    background:#fff;font-family:inherit;font-weight:900;font-size:16px;cursor:pointer;color:var(--navy);\n  }\n  .point-choices button.sel{border-color:var(--gold);background:var(--gold-light);color:#7A5A16;}\n  .filters{display:flex;gap:8px;margin-bottom:14px;flex-wrap:wrap;}\n  .filters select,.filters input{margin-bottom:0;flex:1;min-width:110px;}\n  .student-row{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid #EEF1F4;gap:8px;}\n  .student-row .name{font-weight:700;font-size:14.5px;}\n  .student-row .sub{font-size:12px;color:var(--muted);}\n  .student-row .bal{font-weight:900;color:var(--navy);font-size:15px;white-space:nowrap;}\n  .actions-inline{display:flex;gap:6px;}\n  .toolbar{display:flex;gap:8px;margin-bottom:14px;flex-wrap:wrap;}\n  .toolbar > *{flex:1;min-width:140px;}\n  footer.foot{text-align:center;color:var(--muted);font-size:12px;margin-top:30px;line-height:1.9;}\n  .hidden{display:none !important;}\n  .check-row{display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid #EEF1F4;}\n  .check-row input[type=checkbox]{width:19px;height:19px;flex-shrink:0;margin:0;}\n  .check-row .name{font-weight:700;font-size:14px;}\n  .check-row .sub{font-size:11.5px;color:var(--muted);}\n  .tag{font-size:11.5px;color:var(--muted);}\n  .spinner{display:inline-block;width:16px;height:16px;border:2px solid #ddd;border-top-color:var(--navy);border-radius:50%;animation:spin .7s linear infinite;}\n  @keyframes spin{to{transform:rotate(360deg)}}\n</style>\n</head>\n<body>\n\n<header class=\"top\">\n  <img class=\"logo-header\" src=\"data:image/jpeg;base64,\" alt=\"\u0634\u0639\u0627\u0631 \u0645\u062f\u0631\u0633\u0629 \u0623\u0628\u0648\u062f\u0627\u0648\u0648\u062f \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629\">\n  <div class=\"brand\">\n    <b>\u0645\u062f\u0631\u0633\u0629 \u0623\u0628\u0648\u062f\u0627\u0648\u0648\u062f \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629</b>\n    <span>\u0627\u0644\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0644\u0644\u062a\u0639\u0644\u064a\u0645 \u0628\u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0634\u0631\u0642\u064a\u0629</span>\n  </div>\n</header>\n\n<nav class=\"tabs\">\n  <button data-tab=\"home\" class=\"active\">\u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629</button>\n  <button data-tab=\"student\">\u0627\u0644\u0637\u0627\u0644\u0628</button>\n  <button data-tab=\"nafes\">\u0646\u0627\u0641\u0633</button>\n  <button data-tab=\"activities\">\u0627\u0644\u0623\u0646\u0634\u0637\u0629</button>\n  <button data-tab=\"admin\">\u0627\u0644\u0645\u0634\u0631\u0641\u064a\u0646</button>\n</nav>\n\n<main>\n\n  <!-- ===================== \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 ===================== -->\n  <section id=\"tab-home\">\n    <div class=\"card\">\n      <div class=\"hero-title\">\u2b50 \u0645\u0633\u0627\u0628\u0642\u0629 \u0631\u0635\u064a\u062f \u0627\u0644\u062a\u0645\u064a\u0632</div>\n      <p class=\"hero-tag\">\u0627\u062c\u0645\u0639 \u0646\u0642\u0627\u0637\u0643.. \u0648\u0627\u062d\u0635\u062f \u062c\u0648\u0627\u0626\u0632\u0643<br>\u062a\u0645\u064a\u0651\u0632\u0643 \u0627\u0644\u064a\u0648\u0645.. \u0646\u062c\u0627\u062d\u0643 \u063a\u062f\u064b\u0627</p>\n      <p class=\"hint\">\u0644\u0644\u0627\u0637\u0644\u0627\u0639 \u0639\u0644\u0649 \u0631\u0635\u064a\u062f\u0643 \u0648\u0628\u064a\u0627\u0646\u0627\u062a\u0643\u060c \u0627\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u00ab\u0627\u0644\u0637\u0627\u0644\u0628\u00bb \u0648\u0623\u062f\u062e\u0644 \u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629.</p>\n    </div>\n\n    <div class=\"card\">\n      <h2>\ud83d\udce2 \u0625\u0639\u0644\u0627\u0646 \u0627\u0644\u0645\u0633\u0627\u0628\u0642\u0629</h2>\n      <img class=\"announcement-img\" src=\"data:image/jpeg;base64,\" alt=\"\u0625\u0639\u0644\u0627\u0646 \u0645\u0633\u0627\u0628\u0642\u0629 \u0631\u0635\u064a\u062f \u0627\u0644\u062a\u0645\u064a\u0632\" onclick=\"window.open(this.src,'_blank')\">\n    </div>\n\n    <div class=\"card\">\n      <h2>\u0643\u064a\u0641 \u062a\u062c\u0645\u0639 \u0646\u0642\u0627\u0637\u0643\u061f</h2>\n      <div class=\"points-grid\">\n        <div class=\"item\"><b>\u0627\u0644\u0627\u0646\u0636\u0628\u0627\u0637 \u0648\u0639\u062f\u0645 \u0627\u0644\u063a\u064a\u0627\u0628</b>\u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0627\u0644\u062d\u0636\u0648\u0631 \u0628\u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0645\u062d\u062f\u062f \u0648\u0639\u062f\u0645 \u0627\u0644\u063a\u064a\u0627\u0628.</div>\n        <div class=\"item\"><b>\u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0629 \u0627\u0644\u0641\u0627\u0639\u0644\u0629</b>\u0645\u0634\u0627\u0631\u0643\u062a\u0643 \u0628\u0627\u0644\u0641\u0635\u0644 \u0648\u0627\u0644\u0628\u0631\u0627\u0645\u062c \u0648\u0627\u0644\u0641\u0639\u0627\u0644\u064a\u0627\u062a \u0648\u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0637\u0644\u0627\u0628\u064a.</div>\n        <div class=\"item\"><b>\u0627\u0644\u0633\u0644\u0648\u0643 \u0627\u0644\u0625\u064a\u062c\u0627\u0628\u064a</b>\u0633\u0644\u0648\u0643\u0643 \u0627\u0644\u062d\u0633\u0646 \u0628\u0627\u0644\u0641\u0635\u0644 \u0648\u0628\u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u064a\u0639\u0643\u0633 \u062a\u0645\u064a\u0651\u0632\u0643.</div>\n        <div class=\"item\"><b>\u0646\u0628\u062a\u0639\u062f \u0639\u0646 \u0627\u0644\u0645\u0634\u0627\u062c\u0631\u0627\u062a</b>\u0639\u062f\u0645 \u0627\u0641\u062a\u0639\u0627\u0644 \u0627\u0644\u0634\u062c\u0627\u0631 \u0623\u0648 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0629 \u0641\u064a\u0647 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0648\u062e\u0627\u0631\u062c\u0647\u0627.</div>\n      </div>\n    </div>\n\n    <div class=\"card\" id=\"raffle-public-card\" style=\"display:none\">\n      <h2 id=\"raffle-public-title\">\ud83c\udf89 \u0646\u062a\u064a\u062c\u0629 \u0627\u0644\u0642\u0631\u0639\u0629</h2>\n      <p class=\"hint\" id=\"raffle-public-date\"></p>\n      <div id=\"raffle-public-winners\"></div>\n    </div>\n\n    <div class=\"card\">\n      <h2>\ud83c\udfc6 \u0627\u0644\u0645\u062a\u0635\u062f\u0631\u0648\u0646</h2>\n      <p class=\"hint\">\u0623\u0639\u0644\u0649 \u0661\u0660 \u0637\u0644\u0627\u0628 \u0628\u0631\u0635\u064a\u062f \u0627\u0644\u0646\u0642\u0627\u0637.</p>\n      <div id=\"leaderboard-list\"><div class=\"empty\">\u062c\u0627\u0631\u0650 \u0627\u0644\u062a\u062d\u0645\u064a\u0644...</div></div>\n    </div>\n  </section>\n\n  <!-- ===================== \u0627\u0644\u0637\u0627\u0644\u0628 ===================== -->\n  <section id=\"tab-student\" class=\"hidden\">\n    <div class=\"card\">\n      <h2>\u0627\u0644\u0627\u0633\u062a\u0639\u0644\u0627\u0645 \u0639\u0646 \u0627\u0644\u0631\u0635\u064a\u062f</h2>\n      <label>\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629</label>\n      <input id=\"stu-id\" inputmode=\"numeric\" placeholder=\"\u0645\u062b\u0627\u0644: 1234567890\" />\n      <button class=\"btn gold\" onclick=\"lookupStudent()\">\u0627\u0633\u062a\u0639\u0644\u0627\u0645</button>\n      <div id=\"stu-msg\"></div>\n    </div>\n    <div id=\"stu-result\"></div>\n  </section>\n\n  <!-- ===================== \u0646\u0627\u0641\u0633 ===================== -->\n  <section id=\"tab-nafes\" class=\"hidden\">\n    <div class=\"card\" id=\"nafes-login-required\">\n      <h2>\u0646\u0627\u0641\u0633</h2>\n      <p class=\"hint\">\u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u062d\u0629 \u0644\u0644\u0645\u0634\u0631\u0641\u064a\u0646 \u0648\u0627\u0644\u0645\u0639\u0644\u0645\u064a\u0646. \u0633\u062c\u0651\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0623\u0648\u0644\u064b\u0627 \u0645\u0646 \u062a\u0628\u0648\u064a\u0628 \u00ab\u0627\u0644\u0645\u0634\u0631\u0641\u064a\u0646\u00bb.</p>\n      <button class=\"btn ghost sm\" onclick=\"switchTab('admin')\">\u0627\u0644\u0630\u0647\u0627\u0628 \u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644</button>\n    </div>\n    <div id=\"nafes-content\" class=\"hidden\">\n      <div class=\"card\">\n        <h2>\u0646\u0627\u0641\u0633 (\u0646\u0648\u0627\u062a\u062c \u0627\u0644\u062a\u0639\u0644\u0645)</h2>\n        <p class=\"hint\">\u0627\u0631\u0641\u0639 \u0645\u0644\u0641 \u062f\u0631\u062c\u0627\u062a \u0646\u0627\u0641\u0633 (\u0639\u0645\u0648\u062f\u064a\u0646: \u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629\u060c \u0648\u0627\u0644\u062f\u0631\u062c\u0629) \u2014 \u0648\u0627\u0644\u0646\u0638\u0627\u0645 \u064a\u0635\u0646\u0651\u0641 \u0627\u0644\u0637\u0644\u0627\u0628 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627: \u0623\u064a \u0637\u0627\u0644\u0628 \u062a\u062c\u0627\u0648\u0632\u062a \u062f\u0631\u062c\u062a\u0647 \u062d\u062f \u0627\u0644\u0625\u062a\u0642\u0627\u0646 (<span id=\"nafes-threshold-display\">80</span>) \u064a\u064f\u0633\u062c\u064e\u0651\u0644 \"\u0645\u062a\u0645\u064a\u0632\" \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627\u060c \u0648\u0623\u064a \u0637\u0627\u0644\u0628 \u0644\u0647 \u062f\u0631\u062c\u0629 \u064a\u064f\u0633\u062c\u064e\u0651\u0644 \"\u0645\u0634\u0627\u0631\u0643\". \u0634\u063a\u0644\u062a\u0643 \u0641\u0642\u0637 \u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0639\u062f\u062f \u0648\u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u062a\u0635\u062f\u064a\u0631.</p>\n        <button class=\"btn sm ghost\" onclick=\"document.getElementById('nafes-scores-file').click()\">\ud83d\udcc4 \u0631\u0641\u0639 \u0645\u0644\u0641 \u0627\u0644\u062f\u0631\u062c\u0627\u062a</button>\n        <input id=\"nafes-scores-file\" type=\"file\" accept=\".xlsx,.xls,.csv\" class=\"hidden\" onchange=\"handleNafesScores(event)\" />\n        <p class=\"tag\" id=\"nafes-file-name\"></p>\n      </div>\n\n      <div class=\"card\" id=\"nafes-preview-card\" style=\"display:none\">\n        <h2>\u0645\u0639\u0627\u064a\u0646\u0629 \u0642\u0628\u0644 \u0627\u0644\u062a\u0635\u062f\u064a\u0631</h2>\n        <div class=\"student-row\">\n          <div><div class=\"name\">\ud83d\udc65 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0648\u0646 (\u0643\u0644 \u0645\u0646 \u0644\u0647 \u062f\u0631\u062c\u0629)</div><div class=\"sub\" id=\"nafesPart-names\"></div></div>\n          <div class=\"bal\" id=\"nafesPart-total\">0</div>\n        </div>\n        <div class=\"student-row\">\n          <div><div class=\"name\">\ud83c\udf1f \u0627\u0644\u0645\u062a\u0645\u064a\u0632\u0648\u0646 (\u062a\u062c\u0627\u0648\u0632\u0648\u0627 \u062d\u062f \u0627\u0644\u0625\u062a\u0642\u0627\u0646)</div><div class=\"sub\" id=\"nafesMastery-names\"></div></div>\n          <div class=\"bal\" id=\"nafesMastery-total\">0</div>\n        </div>\n        <button class=\"btn gold\" style=\"margin-top:14px\" onclick=\"submitNafesAll()\">\u062a\u0635\u062f\u064a\u0631 \u0627\u0644\u0643\u0644 \u0644\u0631\u0635\u064a\u062f \u0627\u0644\u062a\u0645\u064a\u0632</button>\n        <div id=\"nafes-msg\"></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ===================== \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u0627\u0644\u0641\u0639\u0627\u0644\u064a\u0627\u062a ===================== -->\n  <section id=\"tab-activities\" class=\"hidden\">\n    <div class=\"card\" id=\"activities-login-required\">\n      <h2>\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u0627\u0644\u0641\u0639\u0627\u0644\u064a\u0627\u062a</h2>\n      <p class=\"hint\">\u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u062d\u0629 \u0644\u0644\u0645\u0634\u0631\u0641\u064a\u0646 \u0648\u0627\u0644\u0645\u0639\u0644\u0645\u064a\u0646. \u0633\u062c\u0651\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0623\u0648\u0644\u064b\u0627 \u0645\u0646 \u062a\u0628\u0648\u064a\u0628 \u00ab\u0627\u0644\u0645\u0634\u0631\u0641\u064a\u0646\u00bb.</p>\n      <button class=\"btn ghost sm\" onclick=\"switchTab('admin')\">\u0627\u0644\u0630\u0647\u0627\u0628 \u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644</button>\n    </div>\n    <div id=\"activities-content\" class=\"hidden\">\n      <div class=\"card\">\n        <h2>\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u0627\u0644\u0641\u0639\u0627\u0644\u064a\u0627\u062a</h2>\n        <p class=\"hint\">\u0643\u0644 \u0627\u0644\u0637\u0644\u0627\u0628 \u0645\u062d\u062f\u0651\u062f\u0648\u0646 \u0627\u0641\u062a\u0631\u0627\u0636\u064a\u064b\u0627. \u0625\u0630\u0627 \u0641\u064a\u0647 \u0637\u0627\u0644\u0628 \u0645\u0627 \u0634\u0627\u0631\u0643 \u0628\u0627\u0644\u0646\u0634\u0627\u0637\u060c \u0634\u0650\u0644 \u0627\u0644\u062a\u062d\u062f\u064a\u062f \u0645\u0646\u0647\u060c \u0648\u0628\u0639\u062f\u0647\u0627 \u0627\u0636\u063a\u0637 \u062a\u0635\u062f\u064a\u0631.</p>\n        <label>\u0627\u0633\u0645 \u0627\u0644\u0646\u0634\u0627\u0637 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a\u060c \u0644\u0644\u062a\u0648\u062b\u064a\u0642 \u0641\u0642\u0637)</label>\n        <input id=\"activities-name\" placeholder=\"\u0645\u062b\u0627\u0644: \u0645\u0633\u0627\u0628\u0642\u0629 \u0627\u0644\u0631\u0633\u0645 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u064a\u0629\" />\n        <div class=\"filters\">\n          <input id=\"activities-search\" placeholder=\"\u0628\u062d\u062b \u0628\u0627\u0644\u0627\u0633\u0645 \u0623\u0648 \u0627\u0644\u0647\u0648\u064a\u0629\" oninput=\"renderSelector('activities')\" />\n          <select id=\"activities-grade\" onchange=\"renderSelector('activities')\"><option value=\"\">\u0643\u0644 \u0627\u0644\u0635\u0641\u0648\u0641</option></select>\n          <select id=\"activities-section\" onchange=\"renderSelector('activities')\"><option value=\"\">\u0643\u0644 \u0627\u0644\u0641\u0635\u0648\u0644</option></select>\n        </div>\n        <div class=\"toolbar\">\n          <button class=\"btn sm ghost\" onclick=\"selectAll('activities', true)\">\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0643\u0644</button>\n          <button class=\"btn sm ghost\" onclick=\"selectAll('activities', false)\">\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u062a\u062d\u062f\u064a\u062f</button>\n        </div>\n        <div id=\"activities-list\"></div>\n        <p class=\"tag\" id=\"activities-count\"></p>\n        <div class=\"row\" style=\"margin-top:14px\">\n          <button class=\"btn gold\" onclick=\"submitSelector('activities','activities_participation',10)\">\u062a\u0635\u062f\u064a\u0631 \u0645\u0634\u0627\u0631\u0643\u0629 \u0644\u0631\u0635\u064a\u062f \u0627\u0644\u062a\u0645\u064a\u0632 (+10)</button>\n        </div>\n        <div id=\"activities-msg\"></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ===================== \u0627\u0644\u0645\u0634\u0631\u0641\u064a\u0646 ===================== -->\n  <section id=\"tab-admin\" class=\"hidden\">\n\n    <!-- \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 -->\n    <div id=\"admin-login-card\" class=\"card\">\n      <h2>\u062f\u062e\u0648\u0644 \u0627\u0644\u0645\u0634\u0631\u0641\u064a\u0646</h2>\n      <p class=\"hint\">\u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0648\u0627\u062d\u062f\u0629 \u0645\u0634\u062a\u0631\u0643\u0629 \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0634\u0631\u0641\u064a\u0646. \u0639\u0646\u062f \u0625\u0636\u0627\u0641\u0629 \u0646\u0642\u0627\u0637\u060c \u0633\u062c\u0651\u0644 \u0627\u0633\u0645\u0643 \u0644\u0644\u0645\u062a\u0627\u0628\u0639\u0629.</p>\n      <label>\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631</label>\n      <input id=\"admin-pass\" type=\"password\" placeholder=\"\u2022\u2022\u2022\u2022\u2022\u2022\" />\n      <button class=\"btn\" onclick=\"adminLogin()\">\u062f\u062e\u0648\u0644</button>\n      <div id=\"admin-login-msg\"></div>\n    </div>\n\n    <!-- \u0625\u0639\u062f\u0627\u062f \u0623\u0648\u0644 \u0645\u0631\u0629 -->\n    <div id=\"admin-setup-card\" class=\"card hidden\">\n      <h2>\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0646\u0638\u0627\u0645 \u0644\u0623\u0648\u0644 \u0645\u0631\u0629</h2>\n      <p class=\"hint\">\u0644\u0645 \u064a\u062a\u0645 \u0636\u0628\u0637 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0627\u0644\u0645\u0634\u0631\u0641\u064a\u0646 \u0628\u0639\u062f. \u0627\u062e\u062a\u0631 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0645\u0634\u062a\u0631\u0643\u0629 \u0644\u0644\u0645\u0634\u0631\u0641\u064a\u0646.</p>\n      <label>\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062c\u062f\u064a\u062f\u0629</label>\n      <input id=\"setup-pass\" type=\"password\" placeholder=\"\u0664 \u0623\u062d\u0631\u0641 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644\" />\n      <button class=\"btn gold\" onclick=\"adminSetup()\">\u062a\u0641\u0639\u064a\u0644</button>\n      <div id=\"admin-setup-msg\"></div>\n    </div>\n\n    <!-- \u0644\u0648\u062d\u0629 \u0627\u0644\u0645\u0634\u0631\u0641 -->\n    <div id=\"admin-panel\" class=\"hidden\">\n\n      <div class=\"card\">\n        <p class=\"tag\" id=\"role-badge\" style=\"margin-bottom:10px\"></p>\n        <div class=\"row\" style=\"margin-bottom:0\">\n          <div>\n            <label>\u0627\u0633\u0645\u0643 (\u064a\u064f\u0633\u062c\u064e\u0651\u0644 \u0645\u0639 \u0643\u0644 \u0639\u0645\u0644\u064a\u0629 \u0625\u0636\u0627\u0641\u0629 \u0646\u0642\u0627\u0637)</label>\n            <input id=\"admin-name\" placeholder=\"\u0645\u062b\u0627\u0644: \u0623. \u0633\u0639\u0648\u062f\" />\n          </div>\n        </div>\n        <button class=\"btn ghost sm\" onclick=\"adminLogout()\">\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062e\u0631\u0648\u062c</button>\n      </div>\n\n      <div class=\"card\">\n        <h2>\u0625\u0636\u0627\u0641\u0629 \u0646\u0642\u0627\u0637 \u0644\u0637\u0627\u0644\u0628</h2>\n        <label>\u0631\u0642\u0645 \u0647\u0648\u064a\u0629 \u0627\u0644\u0637\u0627\u0644\u0628</label>\n        <input id=\"pts-id\" inputmode=\"numeric\" placeholder=\"\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629\" />\n        <label>\u0639\u062f\u062f \u0627\u0644\u0646\u0642\u0627\u0637</label>\n        <div class=\"point-choices\" id=\"pts-values\"></div>\n        <label>\u0633\u0628\u0628 \u0627\u0644\u0625\u0636\u0627\u0641\u0629</label>\n        <select id=\"pts-reason\"></select>\n        <button class=\"btn gold\" onclick=\"submitPoints()\">\u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0646\u0642\u0627\u0637</button>\n        <div id=\"pts-msg\"></div>\n      </div>\n\n      <div class=\"card\">\n        <h2>\u0625\u0636\u0627\u0641\u0629 \u0646\u0642\u0627\u0637 \u062c\u0645\u0627\u0639\u064a\u0629 \u0645\u0646 \u0645\u0644\u0641 \u0625\u0643\u0633\u0644</h2>\n        <p class=\"hint\">\u0645\u062b\u0627\u0644: \u0625\u0636\u0627\u0641\u0629 \u0661\u0660 \u0646\u0642\u0627\u0637 \u0644\u0643\u0644 \u0627\u0644\u0637\u0644\u0627\u0628 \u0627\u0644\u0645\u062a\u0641\u0627\u0639\u0644\u064a\u0646 \u0641\u064a \u0645\u0646\u0635\u0629 \u0646\u0627\u0641\u0633 (\u0646\u0648\u0627\u062a\u062c \u0627\u0644\u062a\u0639\u0644\u0645). \u0627\u0644\u0645\u0644\u0641 \u064a\u062d\u062a\u0627\u062c \u0639\u0645\u0648\u062f \u0648\u0627\u062d\u062f \u0628\u0639\u0646\u0648\u0627\u0646 \"\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629\" (\u0633\u0637\u0631 \u0644\u0643\u0644 \u0637\u0627\u0644\u0628).</p>\n        <label>\u0639\u062f\u062f \u0627\u0644\u0646\u0642\u0627\u0637</label>\n        <div class=\"point-choices\" id=\"bulk-pts-values\"></div>\n        <label>\u0633\u0628\u0628 \u0627\u0644\u0625\u0636\u0627\u0641\u0629</label>\n        <select id=\"bulk-pts-reason\"></select>\n        <button class=\"btn sm ghost\" onclick=\"document.getElementById('bulk-pts-file').click()\">\u0627\u062e\u062a\u064a\u0627\u0631 \u0645\u0644\u0641 \u0627\u0644\u0625\u0643\u0633\u0644</button>\n        <input id=\"bulk-pts-file\" type=\"file\" accept=\".xlsx,.xls,.csv\" class=\"hidden\" onchange=\"handleBulkPointsFile(event)\" />\n        <p class=\"tag\" id=\"bulk-pts-file-name\"></p>\n        <button class=\"btn gold\" id=\"bulk-pts-submit\" onclick=\"submitBulkPoints()\" disabled>\u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0646\u0642\u0627\u0637 \u0644\u0644\u0642\u0627\u0626\u0645\u0629</button>\n        <div id=\"bulk-pts-msg\"></div>\n      </div>\n\n    <!-- \u0643\u0644 \u0645\u0627 \u064a\u0644\u064a \u0645\u062e\u0635\u0635 \u0644\u0644\u0645\u0634\u0631\u0641 \u0627\u0644\u0643\u0627\u0645\u0644 \u0641\u0642\u0637\u060c \u0644\u0627 \u064a\u0638\u0647\u0631 \u0644\u0644\u0645\u0639\u0644\u0645 -->\n    <div id=\"admin-only-section\">\n\n      <div class=\"card\">\n        <h2>\u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0637\u0644\u0627\u0628</h2>\n        <div class=\"toolbar\">\n          <button class=\"btn sm ghost\" onclick=\"openAddStudent()\">+ \u0625\u0636\u0627\u0641\u0629 \u0637\u0627\u0644\u0628</button>\n          <button class=\"btn sm ghost\" onclick=\"document.getElementById('import-file').click()\">\u0627\u0633\u062a\u064a\u0631\u0627\u062f (\u062f\u0645\u062c \u0641\u0642\u0637)</button>\n          <input id=\"import-file\" type=\"file\" accept=\".xlsx,.xls,.csv\" class=\"hidden\" onchange=\"handleImport(event)\" />\n          <button class=\"btn sm ghost\" onclick=\"document.getElementById('sync-file').click()\">\ud83d\udd04 \u062a\u062d\u062f\u064a\u062b \u0643\u0627\u0645\u0644 \u0645\u0646 \u0625\u0643\u0633\u0644</button>\n          <input id=\"sync-file\" type=\"file\" accept=\".xlsx,.xls,.csv\" class=\"hidden\" onchange=\"handleSync(event)\" />\n          <button class=\"btn sm ghost\" onclick=\"exportStudents()\">\u062a\u0635\u062f\u064a\u0631 Excel</button>\n        </div>\n        <p class=\"tag\">\"\u0627\u0633\u062a\u064a\u0631\u0627\u062f\" \u064a\u0636\u064a\u0641 \u0648\u064a\u062d\u062f\u0651\u062b \u0628\u062f\u0648\u0646 \u062d\u0630\u0641 \u0623\u062d\u062f. \"\u062a\u062d\u062f\u064a\u062b \u0643\u0627\u0645\u0644\" \u064a\u062c\u0639\u0644 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0645\u0637\u0627\u0628\u0642\u0629 \u0644\u0644\u0645\u0644\u0641 \u062a\u0645\u0627\u0645\u064b\u0627: \u064a\u0636\u064a\u0641 \u0627\u0644\u062c\u062f\u062f \u0648\u064a\u0646\u0642\u0644 \u0623\u064a \u0637\u0627\u0644\u0628 \u063a\u064a\u0631 \u0645\u0648\u062c\u0648\u062f \u0628\u0627\u0644\u0645\u0644\u0641 \u0625\u0644\u0649 \u0633\u0644\u0629 \u0627\u0644\u0645\u062d\u0630\u0648\u0641\u0627\u062a.</p>\n        <div class=\"filters\">\n          <input id=\"f-search\" placeholder=\"\u0628\u062d\u062b \u0628\u0627\u0644\u0627\u0633\u0645 \u0623\u0648 \u0627\u0644\u0647\u0648\u064a\u0629\" oninput=\"renderStudents()\" />\n          <select id=\"f-grade\" onchange=\"renderStudents()\"><option value=\"\">\u0643\u0644 \u0627\u0644\u0635\u0641\u0648\u0641</option></select>\n          <select id=\"f-section\" onchange=\"renderStudents()\"><option value=\"\">\u0643\u0644 \u0627\u0644\u0641\u0635\u0648\u0644</option></select>\n        </div>\n        <div id=\"students-list\"></div>\n        <p class=\"tag\" id=\"students-count\"></p>\n      </div>\n\n      <!-- \u0646\u0645\u0648\u0630\u062c \u0625\u0636\u0627\u0641\u0629/\u062a\u0639\u062f\u064a\u0644 \u0637\u0627\u0644\u0628 -->\n      <div class=\"card hidden\" id=\"student-form-card\">\n        <h2 id=\"student-form-title\">\u0625\u0636\u0627\u0641\u0629 \u0637\u0627\u0644\u0628</h2>\n        <input type=\"hidden\" id=\"sf-editing-id\" />\n        <label>\u0627\u0644\u0627\u0633\u0645</label>\n        <input id=\"sf-name\" placeholder=\"\u0627\u0633\u0645 \u0627\u0644\u0637\u0627\u0644\u0628\" />\n        <label>\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629</label>\n        <input id=\"sf-nid\" inputmode=\"numeric\" placeholder=\"\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629\" />\n        <div class=\"row\">\n          <div>\n            <label>\u0627\u0644\u0635\u0641</label>\n            <select id=\"sf-grade\"></select>\n          </div>\n          <div>\n            <label>\u0627\u0644\u0641\u0635\u0644</label>\n            <select id=\"sf-section\"></select>\n          </div>\n        </div>\n        <div class=\"row\">\n          <button class=\"btn ghost\" onclick=\"closeStudentForm()\">\u0625\u0644\u063a\u0627\u0621</button>\n          <button class=\"btn gold\" onclick=\"saveStudentForm()\">\u062d\u0641\u0638</button>\n        </div>\n        <div id=\"sf-msg\"></div>\n      </div>\n\n      <div class=\"card\">\n        <h2>\u0633\u0644\u0629 \u0627\u0644\u0645\u062d\u0630\u0648\u0641\u0627\u062a (<span id=\"trash-count\">0</span>)</h2>\n        <div id=\"trash-list\"></div>\n      </div>\n\n      <div class=\"card\">\n        <h2>\ud83c\udfb2 \u0627\u0644\u0642\u0631\u0639\u0629</h2>\n        <p class=\"hint\">\u0633\u062d\u0628 \u0639\u0634\u0648\u0627\u0626\u064a \u0644\u0627\u062e\u062a\u064a\u0627\u0631 \u0637\u0627\u0644\u0628 \u0623\u0648 \u0623\u0643\u062b\u0631 \u2014 \u0644\u0644\u0641\u0639\u0627\u0644\u064a\u0627\u062a \u0648\u0627\u0644\u062a\u062d\u0641\u064a\u0632.</p>\n        <label>\u0645\u0646 \u0636\u0645\u0646</label>\n        <select id=\"raffle-mode\" onchange=\"renderRaffleFilterFields()\">\n          <option value=\"all\">\u0643\u0644 \u0627\u0644\u0637\u0644\u0627\u0628</option>\n          <option value=\"grade\">\u0635\u0641 \u0645\u0639\u064a\u0651\u0646</option>\n          <option value=\"section\">\u0641\u0635\u0644 \u0645\u0639\u064a\u0651\u0646</option>\n          <option value=\"top\">\u0627\u0644\u0645\u062a\u0635\u062f\u0631\u064a\u0646 (\u0623\u0639\u0644\u0649 \u0662\u0660)</option>\n        </select>\n        <div id=\"raffle-filter-fields\"></div>\n        <label>\u0639\u062f\u062f \u0627\u0644\u0641\u0627\u0626\u0632\u064a\u0646</label>\n        <input id=\"raffle-count\" type=\"number\" min=\"1\" max=\"20\" value=\"1\" />\n        <label>\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0642\u0631\u0639\u0629 (\u064a\u0638\u0647\u0631 \u0628\u0627\u0644\u0635\u0641\u062d\u0629 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629)</label>\n        <input id=\"raffle-label\" placeholder=\"\u0645\u062b\u0627\u0644: \u0642\u0631\u0639\u0629 \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\" />\n        <div class=\"row\" style=\"align-items:center;margin-bottom:14px\">\n          <label style=\"margin:0;display:flex;align-items:center;gap:8px;font-weight:500\">\n            <input type=\"checkbox\" id=\"raffle-publish\" style=\"width:auto;margin:0\" checked> \u0646\u0634\u0631 \u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0641\u064a \u0627\u0644\u0635\u0641\u062d\u0629 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629\n          </label>\n        </div>\n        <button class=\"btn gold\" onclick=\"runRaffle()\">\u0633\u062d\u0628 \u0627\u0644\u0642\u0631\u0639\u0629</button>\n        <div id=\"raffle-msg\"></div>\n        <div id=\"raffle-result\"></div>\n      </div>\n\n      <div class=\"card\">\n        <h2>\u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a</h2>\n        <label>\u0627\u0633\u0645 \u0627\u0644\u0645\u062f\u0631\u0633\u0629</label>\n        <input id=\"set-school-name\" />\n        <button class=\"btn sm ghost\" onclick=\"saveSchoolName()\">\u062d\u0641\u0638 \u0627\u0633\u0645 \u0627\u0644\u0645\u062f\u0631\u0633\u0629</button>\n        <hr style=\"margin:18px 0;border:none;border-top:1px solid #EEF1F4\">\n        <label>\u062a\u063a\u064a\u064a\u0631 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0627\u0644\u0645\u0634\u0631\u0641\u064a\u0646 (\u0635\u0644\u0627\u062d\u064a\u0629 \u0643\u0627\u0645\u0644\u0629)</label>\n        <input id=\"set-new-pass\" type=\"password\" placeholder=\"\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062c\u062f\u064a\u062f\u0629\" />\n        <button class=\"btn sm ghost\" onclick=\"changePassword()\">\u062a\u062d\u062f\u064a\u062b \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0627\u0644\u0645\u0634\u0631\u0641\u064a\u0646</button>\n        <hr style=\"margin:18px 0;border:none;border-top:1px solid #EEF1F4\">\n        <label>\u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0627\u0644\u0645\u0639\u0644\u0645\u064a\u0646 (\u0635\u0644\u0627\u062d\u064a\u0629 \u0625\u0636\u0627\u0641\u0629 \u0646\u0642\u0627\u0637 \u0641\u0642\u0637)</label>\n        <input id=\"set-teacher-pass\" type=\"password\" placeholder=\"\u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0627\u0644\u0645\u0639\u0644\u0645\u064a\u0646\" />\n        <button class=\"btn sm ghost\" onclick=\"setTeacherPassword()\">\u062a\u062d\u062f\u064a\u062b \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0627\u0644\u0645\u0639\u0644\u0645\u064a\u0646</button>\n        <hr style=\"margin:18px 0;border:none;border-top:1px solid #EEF1F4\">\n        <label>\u062d\u062f \u0627\u0644\u0625\u062a\u0642\u0627\u0646 \u0641\u064a \u0646\u0627\u0641\u0633 (\u0627\u0644\u062f\u0631\u062c\u0629 \u0627\u0644\u0644\u064a \u0641\u0648\u0642\u0647\u0627 \u064a\u064f\u0639\u062a\u0628\u0631 \u0627\u0644\u0637\u0627\u0644\u0628 \u0645\u062a\u0645\u064a\u0632\u064b\u0627)</label>\n        <input id=\"set-nafes-threshold\" type=\"number\" min=\"0\" max=\"100\" placeholder=\"\u0645\u062b\u0627\u0644: 80\" />\n        <button class=\"btn sm ghost\" onclick=\"saveNafesThreshold()\">\u062d\u0641\u0638 \u062d\u062f \u0627\u0644\u0625\u062a\u0642\u0627\u0646</button>\n        <div id=\"set-msg\"></div>\n      </div>\n\n    </div><!-- /admin-only-section -->\n\n    </div><!-- /admin-panel -->\n  </section>\n\n</main>\n\n<footer class=\"foot\">\n  \u0631\u0635\u064a\u062f \u0627\u0644\u0627\u0646\u0636\u0628\u0627\u0637 \u2014 \u0645\u062f\u0631\u0633\u0629 \u0623\u0628\u0648\u062f\u0627\u0648\u0648\u062f \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629<br>\n  \u062a\u062e\u0632\u064a\u0646 \u0633\u062d\u0627\u0628\u064a \u0639\u0628\u0631 Cloudflare Workers KV\n</footer>\n\n<script>\n/* ============ \u062d\u0627\u0644\u0629 \u0639\u0627\u0645\u0629 ============ */\nlet ADMIN_PASS = sessionStorage.getItem('adminPass') || '';\nlet ADMIN_ROLE = sessionStorage.getItem('adminRole') || ''; // 'admin' | 'teacher'\nlet ADMIN_NAME = localStorage.getItem('adminName') || '';\nlet DATA = null; // \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 (\u0628\u0639\u062f \u062f\u062e\u0648\u0644 \u0627\u0644\u0645\u0634\u0631\u0641/\u0627\u0644\u0645\u0639\u0644\u0645)\nlet SELECTED_POINTS = null;\nlet SELECTED_BULK_POINTS = null;\nlet BULK_IDS = [];\nlet STUDENTS_LITE = null; // {students, grades, sections} - \u064a\u064f\u062d\u0645\u064e\u0651\u0644 \u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u0628\u0639\u062f \u0627\u0644\u062f\u062e\u0648\u0644\nconst SELECTED_IDS = { activities: new Set() };\n\ndocument.addEventListener('DOMContentLoaded', loadLeaderboard);\n\n/* ============ \u062a\u0628\u0648\u064a\u0628\u0627\u062a ============ */\ndocument.querySelectorAll('nav.tabs button').forEach(btn=>{\n  btn.addEventListener('click', ()=> switchTab(btn.dataset.tab));\n});\n\nfunction switchTab(tab){\n  document.querySelectorAll('nav.tabs button').forEach(b=>b.classList.toggle('active', b.dataset.tab===tab));\n  document.querySelectorAll('main > section').forEach(s=>s.classList.add('hidden'));\n  document.getElementById('tab-'+tab).classList.remove('hidden');\n  if(tab === 'admin') initAdminTab();\n  if(tab === 'nafes') initNafesTab();\n  if(tab === 'activities') initSelectorTab('activities');\n}\n\n/* ============ \u0623\u062f\u0648\u0627\u062a \u0645\u0633\u0627\u0639\u062f\u0629 ============ */\nfunction onlyDigits(v){ return (v||'').toString().replace(/[^0-9]/g,''); }\nfunction showMsg(elId, text, type){\n  const el = document.getElementById(elId);\n  el.innerHTML = `<div class=\"msg ${type}\">${text}</div>`;\n}\nfunction clearMsg(elId){ document.getElementById(elId).innerHTML=''; }\n\nasync function api(path, opts={}){\n  const headers = opts.headers || {};\n  headers['Content-Type'] = 'application/json';\n  if(ADMIN_PASS) headers['x-admin-password'] = ADMIN_PASS;\n  const res = await fetch(path, {...opts, headers});\n  const body = await res.json().catch(()=>({}));\n  if(!res.ok) throw new Error(body.error || '\u062d\u062f\u062b \u062e\u0637\u0623 \u063a\u064a\u0631 \u0645\u062a\u0648\u0642\u0639.');\n  return body;\n}\n\n/* ============ \u0627\u0644\u0635\u0641\u062d\u0629 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629: \u0627\u0644\u0645\u062a\u0635\u062f\u0631\u0648\u0646 \u0648\u0646\u062a\u064a\u062c\u0629 \u0627\u0644\u0642\u0631\u0639\u0629 ============ */\nasync function loadLeaderboard(){\n  try{\n    const res = await fetch('/api/leaderboard');\n    const data = await res.json();\n    const list = data.top || [];\n    if(!list.length){\n      document.getElementById('leaderboard-list').innerHTML = '<div class=\"empty\">\u0644\u0627 \u064a\u0648\u062c\u062f \u0628\u064a\u0627\u0646\u0627\u062a \u0628\u0639\u062f.</div>';\n    }else{\n      document.getElementById('leaderboard-list').innerHTML = list.map((s,i)=>`\n        <div class=\"student-row\">\n          <div>\n            <div class=\"name\">${i+1}. ${s.name}</div>\n            <div class=\"sub\">${s.grade} / ${s.section}</div>\n          </div>\n          <div class=\"bal\">${s.balance}</div>\n        </div>\n      `).join('');\n    }\n    if(data.lastRaffle && (data.lastRaffle.winners||[]).length){\n      document.getElementById('raffle-public-card').style.display='';\n      document.getElementById('raffle-public-title').textContent = '\ud83c\udf89 ' + (data.lastRaffle.label || '\u0646\u062a\u064a\u062c\u0629 \u0627\u0644\u0642\u0631\u0639\u0629');\n      document.getElementById('raffle-public-date').textContent = new Date(data.lastRaffle.date).toLocaleString('ar-SA');\n      document.getElementById('raffle-public-winners').innerHTML = data.lastRaffle.winners.map(w=>`\n        <div class=\"student-row\">\n          <div>\n            <div class=\"name\">${w.name}</div>\n            <div class=\"sub\">${w.grade} / ${w.section}</div>\n          </div>\n        </div>`).join('');\n    }\n  }catch(e){\n    document.getElementById('leaderboard-list').innerHTML = '<div class=\"empty\">\u062a\u0639\u0630\u0651\u0631 \u062a\u062d\u0645\u064a\u0644 \u0627\u0644\u0645\u062a\u0635\u062f\u0631\u064a\u0646 \u062d\u0627\u0644\u064a\u064b\u0627.</div>';\n  }\n}\n\n/* ============ \u0646\u0627\u0641\u0633 \u0648\u0627\u0644\u0623\u0646\u0634\u0637\u0629: \u0627\u062e\u062a\u064a\u0627\u0631 \u0637\u0644\u0627\u0628 \u0648\u0625\u0636\u0627\u0641\u0629 \u0646\u0642\u0627\u0637 \u062c\u0645\u0627\u0639\u064a\u0629 ============ */\nconst SELECTOR_PREFIXES = ['activities'];\nlet NAFES_THRESHOLD = 80;\nlet NAFES_GROUPS = null; // { participants: [{nationalId,name,score}], mastery: [...] } \u0628\u0639\u062f \u0631\u0641\u0639 \u0645\u0644\u0641 \u0627\u0644\u062f\u0631\u062c\u0627\u062a\n\nasync function ensureStudentsLite(){\n  if(STUDENTS_LITE) return STUDENTS_LITE;\n  STUDENTS_LITE = await api('/api/admin/students-lite');\n  NAFES_THRESHOLD = STUDENTS_LITE.nafesMasteryThreshold || 80;\n  SELECTOR_PREFIXES.forEach(prefix=>{\n    const g = document.getElementById(prefix+'-grade');\n    const s = document.getElementById(prefix+'-section');\n    if(g) g.innerHTML = '<option value=\"\">\u0643\u0644 \u0627\u0644\u0635\u0641\u0648\u0641</option>' + STUDENTS_LITE.grades.map(x=>`<option value=\"${x}\">${x}</option>`).join('');\n    if(s) s.innerHTML = '<option value=\"\">\u0643\u0644 \u0627\u0644\u0641\u0635\u0648\u0644</option>' + STUDENTS_LITE.sections.map(x=>`<option value=\"${x}\">${x}</option>`).join('');\n  });\n  return STUDENTS_LITE;\n}\n\nasync function initSelectorTab(prefix){\n  if(!ADMIN_PASS){\n    document.getElementById(prefix+'-login-required').classList.remove('hidden');\n    document.getElementById(prefix+'-content').classList.add('hidden');\n    return;\n  }\n  document.getElementById(prefix+'-login-required').classList.add('hidden');\n  document.getElementById(prefix+'-content').classList.remove('hidden');\n  await ensureStudentsLite();\n  if(SELECTED_IDS[prefix].size === 0){\n    STUDENTS_LITE.students.forEach(s => SELECTED_IDS[prefix].add(s.id));\n  }\n  renderSelector(prefix);\n}\n\nasync function initNafesTab(){\n  if(!ADMIN_PASS){\n    document.getElementById('nafes-login-required').classList.remove('hidden');\n    document.getElementById('nafes-content').classList.add('hidden');\n    return;\n  }\n  document.getElementById('nafes-login-required').classList.add('hidden');\n  document.getElementById('nafes-content').classList.remove('hidden');\n  await ensureStudentsLite();\n  document.getElementById('nafes-threshold-display').textContent = NAFES_THRESHOLD;\n}\n\n// \u064a\u0642\u0631\u0623 \u0645\u0644\u0641 \u0627\u0644\u062f\u0631\u062c\u0627\u062a (\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629 + \u0627\u0644\u062f\u0631\u062c\u0629) \u0648\u064a\u0635\u0646\u0651\u0641 \u0627\u0644\u0637\u0644\u0627\u0628 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627 \u0628\u062f\u0648\u0646 \u0623\u064a \u0627\u062e\u062a\u064a\u0627\u0631 \u064a\u062f\u0648\u064a\nfunction handleNafesScores(evt){\n  const file = evt.target.files[0];\n  if(!file) return;\n  const reader = new FileReader();\n  reader.onload = (e)=>{\n    try{\n      const wb = XLSX.read(e.target.result, {type:'binary'});\n      const sheet = wb.Sheets[wb.SheetNames[0]];\n      const rows = XLSX.utils.sheet_to_json(sheet, {defval:''});\n\n      const participants = [];\n      const mastery = [];\n      let skipped = 0;\n\n      rows.forEach(row=>{\n        const nationalId = onlyDigits(row['\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629']||row['nationalId']||row['\u0627\u0644\u0647\u0648\u064a\u0629']||Object.values(row)[0]);\n        const scoreRaw = row['\u0627\u0644\u062f\u0631\u062c\u0629']||row['score']||Object.values(row)[1];\n        const score = Number(scoreRaw);\n        if(!nationalId || isNaN(score)){ skipped++; return; }\n        const student = STUDENTS_LITE.students.find(s=>s.nationalId===nationalId);\n        const name = student ? student.name : nationalId;\n        const entry = { nationalId, name, score };\n        participants.push(entry);\n        if(score >= NAFES_THRESHOLD) mastery.push(entry);\n      });\n\n      NAFES_GROUPS = { participants, mastery };\n      document.getElementById('nafes-file-name').textContent =\n        `\u062a\u0645 \u062a\u062d\u0645\u064a\u0644 ${file.name} \u2014 ${participants.length} \u0637\u0627\u0644\u0628 \u0644\u0647\u0645 \u062f\u0631\u062c\u0629${skipped?`\u060c \u0648\u062a\u062c\u0627\u0648\u0632 ${skipped} \u0635\u0641 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d`:''}.`;\n\n      document.getElementById('nafesPart-total').textContent = participants.length;\n      document.getElementById('nafesPart-names').textContent = participants.map(p=>p.name).join('\u060c ') || '\u2014';\n      document.getElementById('nafesMastery-total').textContent = mastery.length;\n      document.getElementById('nafesMastery-names').textContent = mastery.map(p=>p.name).join('\u060c ') || '\u2014';\n      document.getElementById('nafes-preview-card').style.display = '';\n      clearMsg('nafes-msg');\n    }catch(err){\n      alert('\u062a\u0639\u0630\u0651\u0631 \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0644\u0641. \u062a\u0623\u0643\u062f \u0645\u0646 \u0648\u062c\u0648\u062f \u0639\u0645\u0648\u062f\u064a \"\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629\" \u0648\"\u0627\u0644\u062f\u0631\u062c\u0629\".');\n      NAFES_GROUPS = null;\n      document.getElementById('nafes-preview-card').style.display = 'none';\n    }\n    evt.target.value='';\n  };\n  reader.readAsBinaryString(file);\n}\n\n// \u062a\u0635\u062f\u064a\u0631 \"\u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0648\u0646\" \u0648\"\u0627\u0644\u0645\u062a\u0645\u064a\u0632\u0648\u0646\" (\u0627\u0644\u0645\u062d\u0633\u0648\u0628\u064e\u064a\u0646 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627 \u0645\u0646 \u0627\u0644\u062f\u0631\u062c\u0627\u062a) \u0644\u0631\u0635\u064a\u062f \u0627\u0644\u062a\u0645\u064a\u0632 \u0628\u0636\u063a\u0637\u0629 \u0648\u0627\u062d\u062f\u0629\nasync function submitNafesAll(){\n  clearMsg('nafes-msg');\n  if(!NAFES_GROUPS || !NAFES_GROUPS.participants.length){\n    showMsg('nafes-msg','\u0627\u0631\u0641\u0639 \u0645\u0644\u0641 \u0627\u0644\u062f\u0631\u062c\u0627\u062a \u0623\u0648\u0644\u064b\u0627.','err'); return;\n  }\n  try{\n    const partIds = NAFES_GROUPS.participants.map(p=>p.nationalId);\n    const masteryIds = NAFES_GROUPS.mastery.map(p=>p.nationalId);\n\n    const partRes = await api('/api/admin/bulk-points', {method:'POST', body: JSON.stringify({\n      ids: partIds, points: 5, reasonId: 'nafes_participation', adminName: ADMIN_NAME\n    })});\n    const masteryRes = masteryIds.length ? await api('/api/admin/bulk-points', {method:'POST', body: JSON.stringify({\n      ids: masteryIds, points: 10, reasonId: 'nafes_mastery', adminName: ADMIN_NAME\n    })}) : { successCount: 0, totalRequested: 0 };\n\n    showMsg('nafes-msg', `\u062a\u0645 \u0627\u0644\u062a\u0635\u062f\u064a\u0631 \u0644\u0631\u0635\u064a\u062f \u0627\u0644\u062a\u0645\u064a\u0632 \u2014 \u0645\u0634\u0627\u0631\u0643\u0629: ${partRes.successCount}/${partRes.totalRequested} \u2022 \u0625\u062a\u0642\u0627\u0646: ${masteryRes.successCount}/${masteryRes.totalRequested}`, 'ok');\n\n    NAFES_GROUPS = null;\n    document.getElementById('nafes-preview-card').style.display = 'none';\n    document.getElementById('nafes-file-name').textContent = '';\n  }catch(e){\n    showMsg('nafes-msg', e.message, 'err');\n  }\n}\n\nfunction renderSelector(prefix){\n  if(!STUDENTS_LITE) return;\n  const q = (document.getElementById(prefix+'-search').value||'').trim();\n  const grade = document.getElementById(prefix+'-grade').value;\n  const section = document.getElementById(prefix+'-section').value;\n  let list = STUDENTS_LITE.students.filter(s=>{\n    if(grade && s.grade !== grade) return false;\n    if(section && s.section !== section) return false;\n    if(q && !(s.name.includes(q) || s.nationalId.includes(q))) return false;\n    return true;\n  });\n  list.sort((a,b)=> (a.grade+a.section+a.name).localeCompare(b.grade+b.section+b.name,'ar'));\n\n  const selected = SELECTED_IDS[prefix];\n  document.getElementById(prefix+'-count').textContent = `\u0627\u0644\u0645\u062d\u062f\u0651\u062f\u0648\u0646: ${selected.size} \u2014 \u0627\u0644\u0645\u0639\u0631\u0648\u0636\u0648\u0646: ${list.length} \u0645\u0646 \u0623\u0635\u0644 ${STUDENTS_LITE.students.length}`;\n\n  if(!list.length){\n    document.getElementById(prefix+'-list').innerHTML = '<div class=\"empty\">\u0644\u0627 \u064a\u0648\u062c\u062f \u0637\u0644\u0627\u0628 \u0645\u0637\u0627\u0628\u0642\u064a\u0646.</div>';\n    return;\n  }\n  document.getElementById(prefix+'-list').innerHTML = list.map(s=>`\n    <label class=\"check-row\">\n      <input type=\"checkbox\" data-id=\"${s.id}\" ${selected.has(s.id)?'checked':''} onchange=\"toggleSelect('${prefix}','${s.id}',this.checked)\">\n      <span>\n        <span class=\"name\">${s.name}</span><br>\n        <span class=\"sub\">${s.grade} / ${s.section}</span>\n      </span>\n    </label>\n  `).join('');\n}\n\nfunction toggleSelect(prefix, id, checked){\n  if(checked) SELECTED_IDS[prefix].add(id); else SELECTED_IDS[prefix].delete(id);\n  const el = document.getElementById(prefix+'-count');\n  const shown = el.textContent.match(/\u0627\u0644\u0645\u0639\u0631\u0648\u0636\u0648\u0646:.*$/);\n  el.textContent = `\u0627\u0644\u0645\u062d\u062f\u0651\u062f\u0648\u0646: ${SELECTED_IDS[prefix].size} \u2014 ${shown ? shown[0] : ''}`;\n}\n\nfunction selectAll(prefix, value){\n  if(!STUDENTS_LITE) return;\n  const q = (document.getElementById(prefix+'-search').value||'').trim();\n  const grade = document.getElementById(prefix+'-grade').value;\n  const section = document.getElementById(prefix+'-section').value;\n  STUDENTS_LITE.students.forEach(s=>{\n    if(grade && s.grade !== grade) return;\n    if(section && s.section !== section) return;\n    if(q && !(s.name.includes(q) || s.nationalId.includes(q))) return;\n    if(value) SELECTED_IDS[prefix].add(s.id); else SELECTED_IDS[prefix].delete(s.id);\n  });\n  renderSelector(prefix);\n}\n\nasync function exportGroup(prefix, reasonId, points){\n  const ids = Array.from(SELECTED_IDS[prefix]);\n  if(!ids.length) return { successCount: 0, totalRequested: 0, skipped: true };\n  const nationalIds = STUDENTS_LITE.students.filter(s=>ids.includes(s.id)).map(s=>s.nationalId);\n  return await api('/api/admin/bulk-points', {method:'POST', body: JSON.stringify({\n    ids: nationalIds, points, reasonId, adminName: ADMIN_NAME\n  })});\n}\n\nasync function submitSelector(prefix, reasonId, points){\n  clearMsg(prefix+'-msg');\n  try{\n    const res = await exportGroup(prefix, reasonId, points);\n    if(res.skipped){ showMsg(prefix+'-msg','\u0644\u0627 \u064a\u0648\u062c\u062f \u0637\u0644\u0627\u0628 \u0645\u062d\u062f\u0651\u062f\u0648\u0646 \u0644\u0644\u062a\u0635\u062f\u064a\u0631.','err'); return; }\n    showMsg(prefix+'-msg', `\u062a\u0645 \u0627\u0644\u062a\u0635\u062f\u064a\u0631: \u0623\u064f\u0636\u064a\u0641\u062a \u0627\u0644\u0646\u0642\u0627\u0637 \u0644\u0640${res.successCount} \u0645\u0646 \u0623\u0635\u0644 ${res.totalRequested} \u0637\u0627\u0644\u0628 \u0641\u064a \u0631\u0635\u064a\u062f \u0627\u0644\u062a\u0645\u064a\u0632.`, 'ok');\n    SELECTED_IDS[prefix].clear();\n    STUDENTS_LITE.students.forEach(s => SELECTED_IDS[prefix].add(s.id));\n    renderSelector(prefix);\n    if(prefix === 'activities') document.getElementById('activities-name').value = '';\n  }catch(e){\n    showMsg(prefix+'-msg', e.message, 'err');\n  }\n}\n\n/* ============ \u0627\u0644\u0637\u0627\u0644\u0628: \u0627\u0633\u062a\u0639\u0644\u0627\u0645 ============ */\nasync function lookupStudent(){\n  clearMsg('stu-msg');\n  document.getElementById('stu-result').innerHTML = '';\n  const id = onlyDigits(document.getElementById('stu-id').value);\n  if(!id){ showMsg('stu-msg','\u0623\u062f\u062e\u0644 \u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629.','err'); return; }\n  try{\n    const data = await api('/api/student?id='+id);\n    const rows = (data.history||[]).map(h=>`\n      <tr>\n        <td>${new Date(h.date).toLocaleDateString('ar-SA')}</td>\n        <td>${h.reason}</td>\n        <td><span class=\"pill\">+${h.points}</span></td>\n      </tr>`).join('');\n    document.getElementById('stu-result').innerHTML = `\n      <div class=\"balance-hero\">\n        <div class=\"num\">${data.balance}</div>\n        <div class=\"label\">\u0645\u062c\u0645\u0648\u0639 \u0646\u0642\u0627\u0637 ${data.name}</div>\n        <div class=\"student-meta\">\n          <span>\u0627\u0644\u0635\u0641: ${data.grade}</span>\n          <span>\u0627\u0644\u0641\u0635\u0644: ${data.section}</span>\n        </div>\n      </div>\n      <div class=\"card\">\n        <h2>\u0622\u062e\u0631 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a</h2>\n        ${rows ? `<table><thead><tr><th>\u0627\u0644\u062a\u0627\u0631\u064a\u062e</th><th>\u0627\u0644\u0633\u0628\u0628</th><th>\u0627\u0644\u0646\u0642\u0627\u0637</th></tr></thead><tbody>${rows}</tbody></table>` : '<div class=\"empty\">\u0644\u0627 \u064a\u0648\u062c\u062f \u0633\u062c\u0644 \u0639\u0645\u0644\u064a\u0627\u062a \u0628\u0639\u062f.</div>'}\n      </div>`;\n  }catch(e){\n    showMsg('stu-msg', e.message, 'err');\n  }\n}\n\n/* ============ \u0627\u0644\u0645\u0634\u0631\u0641\u064a\u0646: \u062f\u062e\u0648\u0644 \u0648\u0625\u0639\u062f\u0627\u062f ============ */\nasync function initAdminTab(){\n  if(ADMIN_PASS && DATA){\n    showAdminPanel();\n    return;\n  }\n  // \u0646\u062a\u062d\u0642\u0642 \u0647\u0644 \u0627\u0644\u0646\u0638\u0627\u0645 \u0645\u064f\u0641\u0639\u0651\u0644 \u0645\u0646 \u0642\u0628\u0644 \u0623\u0645 \u064a\u062d\u062a\u0627\u062c \u0625\u0639\u062f\u0627\u062f \u0623\u0648\u0644 \u0645\u0631\u0629\n  try{\n    const res = await fetch('/api/admin/login', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({password:'__probe__'})});\n    const body = await res.json().catch(()=>({}));\n    if(body.needsSetup){\n      document.getElementById('admin-login-card').classList.add('hidden');\n      document.getElementById('admin-setup-card').classList.remove('hidden');\n    } else {\n      document.getElementById('admin-login-card').classList.remove('hidden');\n      document.getElementById('admin-setup-card').classList.add('hidden');\n    }\n  }catch(e){ /* \u062a\u062c\u0627\u0647\u0644\u060c \u0646\u0639\u0631\u0636 \u0634\u0627\u0634\u0629 \u0627\u0644\u062f\u062e\u0648\u0644 \u0627\u0644\u0639\u0627\u062f\u064a\u0629 */ }\n}\n\nasync function adminSetup(){\n  clearMsg('admin-setup-msg');\n  const pass = document.getElementById('setup-pass').value;\n  try{\n    await api('/api/admin/setup', {method:'POST', body: JSON.stringify({password: pass})});\n    ADMIN_PASS = pass;\n    ADMIN_ROLE = 'admin';\n    sessionStorage.setItem('adminPass', pass);\n    sessionStorage.setItem('adminRole', ADMIN_ROLE);\n    document.getElementById('admin-setup-card').classList.add('hidden');\n    await loadAdminData();\n    showAdminPanel();\n  }catch(e){\n    showMsg('admin-setup-msg', e.message, 'err');\n  }\n}\n\nasync function adminLogin(){\n  clearMsg('admin-login-msg');\n  const pass = document.getElementById('admin-pass').value;\n  try{\n    const res = await api('/api/admin/login', {method:'POST', body: JSON.stringify({password: pass})});\n    ADMIN_PASS = pass;\n    ADMIN_ROLE = res.role;\n    sessionStorage.setItem('adminPass', pass);\n    sessionStorage.setItem('adminRole', ADMIN_ROLE);\n    document.getElementById('admin-login-card').classList.add('hidden');\n    await loadAdminData();\n    showAdminPanel();\n  }catch(e){\n    showMsg('admin-login-msg', e.message, 'err');\n  }\n}\n\nfunction adminLogout(){\n  ADMIN_PASS = '';\n  ADMIN_ROLE = '';\n  DATA = null;\n  sessionStorage.removeItem('adminPass');\n  sessionStorage.removeItem('adminRole');\n  document.getElementById('admin-panel').classList.add('hidden');\n  document.getElementById('admin-login-card').classList.remove('hidden');\n  document.getElementById('admin-pass').value = '';\n}\n\nfunction showAdminPanel(){\n  document.getElementById('admin-login-card').classList.add('hidden');\n  document.getElementById('admin-setup-card').classList.add('hidden');\n  document.getElementById('admin-panel').classList.remove('hidden');\n  document.getElementById('admin-name').value = ADMIN_NAME;\n  document.getElementById('admin-name').oninput = (e)=>{ ADMIN_NAME = e.target.value; localStorage.setItem('adminName', ADMIN_NAME); };\n\n  const isAdmin = ADMIN_ROLE === 'admin';\n  document.getElementById('admin-only-section').classList.toggle('hidden', !isAdmin);\n  document.getElementById('role-badge').textContent = isAdmin ? '\u0635\u0644\u0627\u062d\u064a\u0629: \u0645\u0634\u0631\u0641/\u0629 (\u0643\u0627\u0645\u0644\u0629)' : '\u0635\u0644\u0627\u062d\u064a\u0629: \u0645\u0639\u0644\u0645/\u0629 (\u0625\u0636\u0627\u0641\u0629 \u0646\u0642\u0627\u0637 \u0641\u0642\u0637)';\n\n  renderPointChoices();\n  renderReasons();\n  renderBulkPointChoices();\n  renderBulkReasons();\n\n  if(isAdmin){\n    renderFilters();\n    renderStudents();\n    renderTrash();\n    renderRaffleFilterFields();\n    document.getElementById('set-school-name').value = DATA.settings.schoolName;\n    document.getElementById('set-nafes-threshold').value = DATA.settings.nafesMasteryThreshold || 80;\n  }\n}\n\nasync function loadAdminData(){\n  DATA = await api('/api/admin/data');\n}\n\n/* ============ \u0625\u0636\u0627\u0641\u0629 \u0646\u0642\u0627\u0637 ============ */\nfunction renderPointChoices(){\n  const wrap = document.getElementById('pts-values');\n  wrap.innerHTML = DATA.settings.pointValues.map(v=>`<button type=\"button\" onclick=\"selectPoints(${v})\">${v}</button>`).join('');\n}\nfunction selectPoints(v){\n  SELECTED_POINTS = v;\n  document.querySelectorAll('#pts-values button').forEach(b=>{\n    b.classList.toggle('sel', Number(b.textContent) === v);\n  });\n}\nfunction renderReasons(){\n  const sel = document.getElementById('pts-reason');\n  sel.innerHTML = DATA.settings.reasons.map(r=>`<option value=\"${r.id}\" data-points=\"${r.points}\">${r.label} (+${r.points})</option>`).join('');\n  sel.onchange = ()=>{\n    const opt = sel.selectedOptions[0];\n    if(opt) selectPoints(Number(opt.dataset.points));\n  };\n  if(sel.selectedOptions[0]) selectPoints(Number(sel.selectedOptions[0].dataset.points));\n}\nasync function submitPoints(){\n  clearMsg('pts-msg');\n  const nationalId = onlyDigits(document.getElementById('pts-id').value);\n  if(!nationalId){ showMsg('pts-msg','\u0623\u062f\u062e\u0644 \u0631\u0642\u0645 \u0647\u0648\u064a\u0629 \u0627\u0644\u0637\u0627\u0644\u0628.','err'); return; }\n  if(!SELECTED_POINTS){ showMsg('pts-msg','\u0627\u062e\u062a\u0631 \u0639\u062f\u062f \u0627\u0644\u0646\u0642\u0627\u0637.','err'); return; }\n  const reasonId = document.getElementById('pts-reason').value;\n  try{\n    const res = await api('/api/admin/points', {method:'POST', body: JSON.stringify({\n      nationalId, points: SELECTED_POINTS, reasonId, adminName: ADMIN_NAME\n    })});\n    showMsg('pts-msg', `\u062a\u0645\u062a \u0625\u0636\u0627\u0641\u0629 ${SELECTED_POINTS} \u0646\u0642\u0637\u0629 \u0644\u0640${res.name}. \u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u062c\u062f\u064a\u062f: ${res.newBalance}`, 'ok');\n    document.getElementById('pts-id').value='';\n    await loadAdminData();\n    renderStudents();\n  }catch(e){\n    showMsg('pts-msg', e.message, 'err');\n  }\n}\n\n/* ============ \u0625\u0636\u0627\u0641\u0629 \u0646\u0642\u0627\u0637 \u062c\u0645\u0627\u0639\u064a\u0629 \u0645\u0646 \u0625\u0643\u0633\u0644 ============ */\nfunction renderBulkPointChoices(){\n  const wrap = document.getElementById('bulk-pts-values');\n  wrap.innerHTML = DATA.settings.pointValues.map(v=>`<button type=\"button\" onclick=\"selectBulkPoints(${v})\">${v}</button>`).join('');\n}\nfunction selectBulkPoints(v){\n  SELECTED_BULK_POINTS = v;\n  document.querySelectorAll('#bulk-pts-values button').forEach(b=>{\n    b.classList.toggle('sel', Number(b.textContent) === v);\n  });\n}\nfunction renderBulkReasons(){\n  const sel = document.getElementById('bulk-pts-reason');\n  sel.innerHTML = DATA.settings.reasons.map(r=>`<option value=\"${r.id}\" data-points=\"${r.points}\">${r.label} (+${r.points})</option>`).join('');\n  sel.onchange = ()=>{\n    const opt = sel.selectedOptions[0];\n    if(opt) selectBulkPoints(Number(opt.dataset.points));\n  };\n  if(sel.selectedOptions[0]) selectBulkPoints(Number(sel.selectedOptions[0].dataset.points));\n}\n\nfunction handleBulkPointsFile(evt){\n  const file = evt.target.files[0];\n  if(!file) return;\n  const reader = new FileReader();\n  reader.onload = (e)=>{\n    try{\n      const wb = XLSX.read(e.target.result, {type:'binary'});\n      const sheet = wb.Sheets[wb.SheetNames[0]];\n      const rows = XLSX.utils.sheet_to_json(sheet, {defval:''});\n      const ids = [];\n      rows.forEach(row=>{\n        const id = onlyDigits(row['\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629']||row['nationalId']||row['\u0627\u0644\u0647\u0648\u064a\u0629']||Object.values(row)[0]);\n        if(id) ids.push(id);\n      });\n      BULK_IDS = [...new Set(ids)];\n      document.getElementById('bulk-pts-file-name').textContent = `\u062a\u0645 \u062a\u062d\u0645\u064a\u0644 ${file.name} \u2014 \u0639\u062f\u062f \u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u0647\u0648\u064a\u0629: ${BULK_IDS.length}`;\n      document.getElementById('bulk-pts-submit').disabled = BULK_IDS.length === 0;\n    }catch(err){\n      document.getElementById('bulk-pts-file-name').textContent = '';\n      alert('\u062a\u0639\u0630\u0651\u0631 \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0644\u0641. \u062a\u0623\u0643\u062f \u0645\u0646 \u0648\u062c\u0648\u062f \u0639\u0645\u0648\u062f \"\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629\".');\n      BULK_IDS = [];\n      document.getElementById('bulk-pts-submit').disabled = true;\n    }\n    evt.target.value='';\n  };\n  reader.readAsBinaryString(file);\n}\n\nasync function submitBulkPoints(){\n  clearMsg('bulk-pts-msg');\n  if(!BULK_IDS.length){ showMsg('bulk-pts-msg','\u0627\u062e\u062a\u0631 \u0645\u0644\u0641 \u064a\u062d\u062a\u0648\u064a \u0623\u0631\u0642\u0627\u0645 \u0647\u0648\u064a\u0629 \u0623\u0648\u0644\u064b\u0627.','err'); return; }\n  if(!SELECTED_BULK_POINTS){ showMsg('bulk-pts-msg','\u0627\u062e\u062a\u0631 \u0639\u062f\u062f \u0627\u0644\u0646\u0642\u0627\u0637.','err'); return; }\n  const reasonId = document.getElementById('bulk-pts-reason').value;\n  if(!confirm(`\u0633\u064a\u062a\u0645 \u0625\u0636\u0627\u0641\u0629 ${SELECTED_BULK_POINTS} \u0646\u0642\u0637\u0629 \u0644\u0640${BULK_IDS.length} \u0637\u0627\u0644\u0628. \u0645\u062a\u0627\u0628\u0639\u0629\u061f`)) return;\n  try{\n    const res = await api('/api/admin/bulk-points', {method:'POST', body: JSON.stringify({\n      ids: BULK_IDS, points: SELECTED_BULK_POINTS, reasonId, adminName: ADMIN_NAME\n    })});\n    let msg = `\u062a\u0645\u062a \u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0646\u0642\u0627\u0637 \u0644\u0640${res.successCount} \u0645\u0646 \u0623\u0635\u0644 ${res.totalRequested} \u0637\u0627\u0644\u0628.`;\n    if(res.notFound && res.notFound.length){\n      msg += ` \u0644\u0645 \u064a\u062a\u0645 \u0627\u0644\u0639\u062b\u0648\u0631 \u0639\u0644\u0649 ${res.notFound.length} \u0631\u0642\u0645 \u0647\u0648\u064a\u0629 (${res.notFound.slice(0,5).join('\u060c ')}${res.notFound.length>5?'...':''}).`;\n    }\n    showMsg('bulk-pts-msg', msg, res.notFound && res.notFound.length ? 'err' : 'ok');\n    BULK_IDS = [];\n    document.getElementById('bulk-pts-submit').disabled = true;\n    document.getElementById('bulk-pts-file-name').textContent = '';\n    if(DATA.students && DATA.students.length) await loadAdminData();\n    if(document.getElementById('students-list')) try{ renderStudents(); }catch(e){}\n  }catch(e){\n    showMsg('bulk-pts-msg', e.message, 'err');\n  }\n}\n\n/* ============ \u0641\u0644\u0627\u062a\u0631 \u0648\u0639\u0631\u0636 \u0627\u0644\u0637\u0644\u0627\u0628 ============ */\nfunction renderFilters(){\n  const gradeSel = document.getElementById('f-grade');\n  const sectionSel = document.getElementById('f-section');\n  gradeSel.innerHTML = '<option value=\"\">\u0643\u0644 \u0627\u0644\u0635\u0641\u0648\u0641</option>' + DATA.settings.grades.map(g=>`<option value=\"${g}\">${g}</option>`).join('');\n  sectionSel.innerHTML = '<option value=\"\">\u0643\u0644 \u0627\u0644\u0641\u0635\u0648\u0644</option>' + DATA.settings.sections.map(s=>`<option value=\"${s}\">${s}</option>`).join('');\n}\nfunction renderStudents(){\n  const q = (document.getElementById('f-search').value||'').trim();\n  const grade = document.getElementById('f-grade').value;\n  const section = document.getElementById('f-section').value;\n  let list = DATA.students.filter(s=>{\n    if(grade && s.grade !== grade) return false;\n    if(section && s.section !== section) return false;\n    if(q && !(s.name.includes(q) || s.nationalId.includes(q))) return false;\n    return true;\n  });\n  // \u0641\u0631\u0632 \u0628\u0627\u0644\u0635\u0641 \u062b\u0645 \u0627\u0644\u0641\u0635\u0644 \u062b\u0645 \u0627\u0644\u0627\u0633\u0645\n  list.sort((a,b)=> (a.grade+a.section+a.name).localeCompare(b.grade+b.section+a.name,'ar'));\n\n  document.getElementById('students-count').textContent = `\u0639\u062f\u062f \u0627\u0644\u0637\u0644\u0627\u0628 \u0627\u0644\u0645\u0639\u0631\u0648\u0636\u064a\u0646: ${list.length} \u0645\u0646 \u0623\u0635\u0644 ${DATA.students.length}`;\n\n  if(!list.length){\n    document.getElementById('students-list').innerHTML = '<div class=\"empty\">\u0644\u0627 \u064a\u0648\u062c\u062f \u0637\u0644\u0627\u0628 \u0645\u0637\u0627\u0628\u0642\u064a\u0646.</div>';\n    return;\n  }\n  document.getElementById('students-list').innerHTML = list.map(s=>`\n    <div class=\"student-row\">\n      <div>\n        <div class=\"name\">${s.name}</div>\n        <div class=\"sub\">${s.grade} / ${s.section} \u2014 \u0647\u0648\u064a\u0629: ${s.nationalId}</div>\n      </div>\n      <div class=\"actions-inline\">\n        <div class=\"bal\">${s.balance}</div>\n        <button class=\"btn sm ghost\" onclick=\"openEditStudent('${s.id}')\">\u062a\u0639\u062f\u064a\u0644</button>\n        <button class=\"btn sm danger\" onclick=\"deleteStudent('${s.id}')\">\u062d\u0630\u0641</button>\n      </div>\n    </div>\n  `).join('');\n}\n\n/* ============ \u0625\u0636\u0627\u0641\u0629 / \u062a\u0639\u062f\u064a\u0644 \u0637\u0627\u0644\u0628 ============ */\nfunction fillGradeSectionSelects(){\n  document.getElementById('sf-grade').innerHTML = DATA.settings.grades.map(g=>`<option value=\"${g}\">${g}</option>`).join('');\n  document.getElementById('sf-section').innerHTML = DATA.settings.sections.map(s=>`<option value=\"${s}\">${s}</option>`).join('');\n}\nfunction openAddStudent(){\n  fillGradeSectionSelects();\n  document.getElementById('student-form-title').textContent = '\u0625\u0636\u0627\u0641\u0629 \u0637\u0627\u0644\u0628';\n  document.getElementById('sf-editing-id').value = '';\n  document.getElementById('sf-name').value = '';\n  document.getElementById('sf-nid').value = '';\n  clearMsg('sf-msg');\n  document.getElementById('student-form-card').classList.remove('hidden');\n  document.getElementById('student-form-card').scrollIntoView({behavior:'smooth'});\n}\nfunction openEditStudent(id){\n  const s = DATA.students.find(x=>x.id===id);\n  if(!s) return;\n  fillGradeSectionSelects();\n  document.getElementById('student-form-title').textContent = '\u062a\u0639\u062f\u064a\u0644 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0637\u0627\u0644\u0628';\n  document.getElementById('sf-editing-id').value = id;\n  document.getElementById('sf-name').value = s.name;\n  document.getElementById('sf-nid').value = s.nationalId;\n  document.getElementById('sf-grade').value = s.grade;\n  document.getElementById('sf-section').value = s.section;\n  clearMsg('sf-msg');\n  document.getElementById('student-form-card').classList.remove('hidden');\n  document.getElementById('student-form-card').scrollIntoView({behavior:'smooth'});\n}\nfunction closeStudentForm(){\n  document.getElementById('student-form-card').classList.add('hidden');\n}\nasync function saveStudentForm(){\n  clearMsg('sf-msg');\n  const editingId = document.getElementById('sf-editing-id').value;\n  const name = document.getElementById('sf-name').value.trim();\n  const nationalId = onlyDigits(document.getElementById('sf-nid').value);\n  const grade = document.getElementById('sf-grade').value;\n  const section = document.getElementById('sf-section').value;\n\n  if(!name || !nationalId){ showMsg('sf-msg','\u0623\u062f\u062e\u0644 \u0627\u0644\u0627\u0633\u0645 \u0648\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629.','err'); return; }\n\n  const clash = DATA.students.find(s=> s.nationalId === nationalId && s.id !== editingId);\n  if(clash){ showMsg('sf-msg', `\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629 \u0645\u0633\u062a\u062e\u062f\u0645 \u062d\u0627\u0644\u064a\u064b\u0627 \u0644\u0637\u0627\u0644\u0628 \u0622\u062e\u0631 (${clash.name}).`, 'err'); return; }\n\n  if(editingId){\n    const s = DATA.students.find(x=>x.id===editingId);\n    Object.assign(s, {name, nationalId, grade, section});\n  }else{\n    DATA.students.push({\n      id: 'stu_'+Date.now()+'_'+Math.random().toString(36).slice(2,7),\n      name, nationalId, grade, section, balance: 0, history: []\n    });\n  }\n  await persistStudents();\n  closeStudentForm();\n  renderStudents();\n}\n\nasync function deleteStudent(id){\n  const s = DATA.students.find(x=>x.id===id);\n  if(!s) return;\n  if(!confirm(`\u0646\u0642\u0644 ${s.name} \u0625\u0644\u0649 \u0633\u0644\u0629 \u0627\u0644\u0645\u062d\u0630\u0648\u0641\u0627\u062a\u061f`)) return;\n  DATA.students = DATA.students.filter(x=>x.id!==id);\n  DATA.trash = DATA.trash || [];\n  DATA.trash.push({...s, deletedAt: new Date().toISOString()});\n  await persistStudents();\n  renderStudents();\n  renderTrash();\n}\n\nfunction renderTrash(){\n  const trash = DATA.trash || [];\n  document.getElementById('trash-count').textContent = trash.length;\n  if(!trash.length){\n    document.getElementById('trash-list').innerHTML = '<div class=\"empty\">\u0633\u0644\u0629 \u0627\u0644\u0645\u062d\u0630\u0648\u0641\u0627\u062a \u0641\u0627\u0631\u063a\u0629.</div>';\n    return;\n  }\n  document.getElementById('trash-list').innerHTML = trash.map(s=>`\n    <div class=\"student-row\">\n      <div>\n        <div class=\"name\">${s.name}</div>\n        <div class=\"sub\">${s.grade} / ${s.section} \u2014 \u0647\u0648\u064a\u0629: ${s.nationalId}</div>\n      </div>\n      <div class=\"actions-inline\">\n        <button class=\"btn sm ghost\" onclick=\"restoreStudent('${s.id}')\">\u0627\u0633\u062a\u0639\u0627\u062f\u0629</button>\n      </div>\n    </div>\n  `).join('');\n}\nasync function restoreStudent(id){\n  const s = (DATA.trash||[]).find(x=>x.id===id);\n  if(!s) return;\n  DATA.trash = DATA.trash.filter(x=>x.id!==id);\n  const {deletedAt, ...clean} = s;\n  DATA.students.push(clean);\n  await persistStudents();\n  renderStudents();\n  renderTrash();\n}\n\nasync function persistStudents(){\n  await api('/api/admin/data', {method:'POST', body: JSON.stringify({settings: DATA.settings, students: DATA.students, trash: DATA.trash})});\n}\n\n/* ============ \u0627\u0633\u062a\u064a\u0631\u0627\u062f \u0645\u0646 \u0625\u0643\u0633\u0644 ============ */\nfunction handleImport(evt){\n  const file = evt.target.files[0];\n  if(!file) return;\n  const reader = new FileReader();\n  reader.onload = async (e)=>{\n    try{\n      const wb = XLSX.read(e.target.result, {type:'binary'});\n      const sheet = wb.Sheets[wb.SheetNames[0]];\n      const rows = XLSX.utils.sheet_to_json(sheet, {defval:''});\n      let added=0, updated=0, skipped=0;\n      rows.forEach(row=>{\n        const name = (row['\u0627\u0644\u0627\u0633\u0645']||row['name']||'').toString().trim();\n        const nationalId = onlyDigits(row['\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629']||row['nationalId']||row['\u0627\u0644\u0647\u0648\u064a\u0629']||'');\n        const grade = (row['\u0627\u0644\u0635\u0641']||row['grade']||'').toString().trim() || DATA.settings.grades[0];\n        const section = (row['\u0627\u0644\u0641\u0635\u0644']||row['section']||'').toString().trim() || DATA.settings.sections[0];\n        if(!name || !nationalId){ skipped++; return; }\n        const existing = DATA.students.find(s=>s.nationalId===nationalId);\n        if(existing){\n          Object.assign(existing, {name, grade, section});\n          updated++;\n        }else{\n          DATA.students.push({id:'stu_'+Date.now()+'_'+Math.random().toString(36).slice(2,7), name, nationalId, grade, section, balance:0, history:[]});\n          added++;\n        }\n      });\n      await persistStudents();\n      renderStudents();\n      alert(`\u062a\u0645 \u0627\u0644\u0627\u0633\u062a\u064a\u0631\u0627\u062f: \u0625\u0636\u0627\u0641\u0629 ${added}\u060c \u062a\u062d\u062f\u064a\u062b ${updated}${skipped? `\u060c \u0648\u062a\u062c\u0627\u0648\u0632 ${skipped} \u0635\u0641 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d`:''}.`);\n    }catch(err){\n      alert('\u062a\u0639\u0630\u0651\u0631 \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0644\u0641. \u062a\u0623\u0643\u062f \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u062f\u0629: \u0627\u0644\u0627\u0633\u0645\u060c \u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629\u060c \u0627\u0644\u0635\u0641\u060c \u0627\u0644\u0641\u0635\u0644.');\n    }\n    evt.target.value='';\n  };\n  reader.readAsBinaryString(file);\n}\n\n/* ============ \u062a\u062d\u062f\u064a\u062b \u0643\u0627\u0645\u0644 \u0645\u0646 \u0625\u0643\u0633\u0644 (\u062d\u0630\u0641 \u0627\u0644\u0645\u0646\u0642\u0648\u0644 + \u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u062c\u062f\u064a\u062f) ============ */\nfunction handleSync(evt){\n  const file = evt.target.files[0];\n  if(!file) return;\n  const reader = new FileReader();\n  reader.onload = async (e)=>{\n    try{\n      const wb = XLSX.read(e.target.result, {type:'binary'});\n      const sheet = wb.Sheets[wb.SheetNames[0]];\n      const rows = XLSX.utils.sheet_to_json(sheet, {defval:''});\n\n      const fileStudents = [];\n      let skipped = 0;\n      rows.forEach(row=>{\n        const name = (row['\u0627\u0644\u0627\u0633\u0645']||row['name']||'').toString().trim();\n        const nationalId = onlyDigits(row['\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629']||row['nationalId']||row['\u0627\u0644\u0647\u0648\u064a\u0629']||'');\n        const grade = (row['\u0627\u0644\u0635\u0641']||row['grade']||'').toString().trim() || DATA.settings.grades[0];\n        const section = (row['\u0627\u0644\u0641\u0635\u0644']||row['section']||'').toString().trim() || DATA.settings.sections[0];\n        if(!name || !nationalId){ skipped++; return; }\n        fileStudents.push({name, nationalId, grade, section});\n      });\n\n      if(!fileStudents.length){\n        alert('\u0644\u0645 \u064a\u062a\u0645 \u0627\u0644\u0639\u062b\u0648\u0631 \u0639\u0644\u0649 \u0623\u064a \u0635\u0641\u0648\u0641 \u0635\u0627\u0644\u062d\u0629 \u0628\u0627\u0644\u0645\u0644\u0641.');\n        evt.target.value=''; return;\n      }\n\n      const fileIds = new Set(fileStudents.map(s=>s.nationalId));\n      const toRemove = DATA.students.filter(s=>!fileIds.has(s.nationalId));\n\n      const confirmMsg = `\u062a\u062d\u062f\u064a\u062b \u0643\u0627\u0645\u0644 \u0645\u0646 \u0627\u0644\u0645\u0644\u0641:\\n- \u0633\u064a\u064f\u0636\u0627\u0641/\u064a\u064f\u062d\u062f\u064e\u0651\u062b ${fileStudents.length} \u0637\u0627\u0644\u0628.\\n- \u0633\u064a\u064f\u0646\u0642\u0644 ${toRemove.length} \u0637\u0627\u0644\u0628 \u063a\u064a\u0631 \u0645\u0648\u062c\u0648\u062f \u0628\u0627\u0644\u0645\u0644\u0641 \u0625\u0644\u0649 \u0633\u0644\u0629 \u0627\u0644\u0645\u062d\u0630\u0648\u0641\u0627\u062a.\\n${skipped?`- \u062a\u0645 \u062a\u062c\u0627\u0648\u0632 ${skipped} \u0635\u0641 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d.\\n`:''}\\n\u0647\u0644 \u062a\u0631\u064a\u062f \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629\u061f`;\n      if(!confirm(confirmMsg)){ evt.target.value=''; return; }\n\n      // \u0646\u0642\u0644 \u063a\u064a\u0631 \u0627\u0644\u0645\u0648\u062c\u0648\u062f\u064a\u0646 \u0644\u0644\u0633\u0644\u0629\n      DATA.trash = DATA.trash || [];\n      toRemove.forEach(s=> DATA.trash.push({...s, deletedAt: new Date().toISOString()}));\n      let remaining = DATA.students.filter(s=>fileIds.has(s.nationalId));\n\n      let added=0, updated=0;\n      fileStudents.forEach(fs=>{\n        const existing = remaining.find(s=>s.nationalId===fs.nationalId);\n        if(existing){\n          Object.assign(existing, {name:fs.name, grade:fs.grade, section:fs.section});\n          updated++;\n        }else{\n          remaining.push({id:'stu_'+Date.now()+'_'+Math.random().toString(36).slice(2,7), name:fs.name, nationalId:fs.nationalId, grade:fs.grade, section:fs.section, balance:0, history:[]});\n          added++;\n        }\n      });\n\n      DATA.students = remaining;\n      await persistStudents();\n      renderStudents();\n      renderTrash();\n      alert(`\u062a\u0645 \u0627\u0644\u062a\u062d\u062f\u064a\u062b \u0627\u0644\u0643\u0627\u0645\u0644: \u0625\u0636\u0627\u0641\u0629 ${added}\u060c \u062a\u062d\u062f\u064a\u062b ${updated}\u060c \u0646\u0642\u0644 ${toRemove.length} \u0625\u0644\u0649 \u0633\u0644\u0629 \u0627\u0644\u0645\u062d\u0630\u0648\u0641\u0627\u062a.`);\n    }catch(err){\n      alert('\u062a\u0639\u0630\u0651\u0631 \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0644\u0641. \u062a\u0623\u0643\u062f \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u062f\u0629: \u0627\u0644\u0627\u0633\u0645\u060c \u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629\u060c \u0627\u0644\u0635\u0641\u060c \u0627\u0644\u0641\u0635\u0644.');\n    }\n    evt.target.value='';\n  };\n  reader.readAsBinaryString(file);\n}\n\nfunction exportStudents(){\n  const rows = DATA.students.map(s=>({\n    '\u0627\u0644\u0627\u0633\u0645': s.name, '\u0631\u0642\u0645 \u0627\u0644\u0647\u0648\u064a\u0629': s.nationalId, '\u0627\u0644\u0635\u0641': s.grade, '\u0627\u0644\u0641\u0635\u0644': s.section, '\u0627\u0644\u0631\u0635\u064a\u062f': s.balance\n  }));\n  const ws = XLSX.utils.json_to_sheet(rows);\n  const wb = XLSX.utils.book_new();\n  XLSX.utils.book_append_sheet(wb, ws, '\u0627\u0644\u0637\u0644\u0627\u0628');\n  XLSX.writeFile(wb, '\u0637\u0644\u0627\u0628_\u0623\u0628\u0648\u062f\u0627\u0648\u0648\u062f.xlsx');\n}\n\n/* ============ \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a ============ */\nasync function saveSchoolName(){\n  clearMsg('set-msg');\n  DATA.settings.schoolName = document.getElementById('set-school-name').value.trim() || DATA.settings.schoolName;\n  await persistStudents();\n  showMsg('set-msg','\u062a\u0645 \u0627\u0644\u062d\u0641\u0638.','ok');\n}\nasync function saveNafesThreshold(){\n  clearMsg('set-msg');\n  const val = Number(document.getElementById('set-nafes-threshold').value);\n  if(!val || val < 0 || val > 100){ showMsg('set-msg','\u0623\u062f\u062e\u0644 \u0631\u0642\u0645\u064b\u0627 \u0635\u062d\u064a\u062d\u064b\u0627 \u0628\u064a\u0646 0 \u0648100.','err'); return; }\n  DATA.settings.nafesMasteryThreshold = val;\n  await persistStudents();\n  showMsg('set-msg','\u062a\u0645 \u062d\u0641\u0638 \u062d\u062f \u0627\u0644\u0625\u062a\u0642\u0627\u0646.','ok');\n}\nasync function changePassword(){\n  clearMsg('set-msg');\n  const newPass = document.getElementById('set-new-pass').value;\n  if(newPass.length < 4){ showMsg('set-msg','\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0642\u0635\u064a\u0631\u0629 \u062c\u062f\u064b\u0627.','err'); return; }\n  try{\n    await api('/api/admin/change-password', {method:'POST', body: JSON.stringify({newPassword:newPass})});\n    ADMIN_PASS = newPass;\n    sessionStorage.setItem('adminPass', newPass);\n    document.getElementById('set-new-pass').value='';\n    showMsg('set-msg','\u062a\u0645 \u062a\u062d\u062f\u064a\u062b \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0627\u0644\u0645\u0634\u0631\u0641\u064a\u0646.','ok');\n  }catch(e){\n    showMsg('set-msg', e.message, 'err');\n  }\n}\n\nasync function setTeacherPassword(){\n  clearMsg('set-msg');\n  const pass = document.getElementById('set-teacher-pass').value;\n  if(pass.length < 4){ showMsg('set-msg','\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0642\u0635\u064a\u0631\u0629 \u062c\u062f\u064b\u0627.','err'); return; }\n  try{\n    await api('/api/admin/teacher-password', {method:'POST', body: JSON.stringify({password:pass})});\n    document.getElementById('set-teacher-pass').value='';\n    showMsg('set-msg','\u062a\u0645 \u062a\u062d\u062f\u064a\u062b \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0627\u0644\u0645\u0639\u0644\u0645\u064a\u0646.','ok');\n  }catch(e){\n    showMsg('set-msg', e.message, 'err');\n  }\n}\n\n/* ============ \u0627\u0644\u0642\u0631\u0639\u0629 ============ */\nfunction renderRaffleFilterFields(){\n  const mode = document.getElementById('raffle-mode').value;\n  const wrap = document.getElementById('raffle-filter-fields');\n  if(mode === 'grade'){\n    wrap.innerHTML = `<label>\u0627\u0644\u0635\u0641</label><select id=\"raffle-grade\">${DATA.settings.grades.map(g=>`<option value=\"${g}\">${g}</option>`).join('')}</select>`;\n  }else if(mode === 'section'){\n    wrap.innerHTML = `<label>\u0627\u0644\u0641\u0635\u0644</label><select id=\"raffle-section\">${DATA.settings.sections.map(s=>`<option value=\"${s}\">${s}</option>`).join('')}</select>`;\n  }else{\n    wrap.innerHTML = '';\n  }\n}\nasync function runRaffle(){\n  clearMsg('raffle-msg');\n  document.getElementById('raffle-result').innerHTML='';\n  const mode = document.getElementById('raffle-mode').value;\n  const count = Number(document.getElementById('raffle-count').value) || 1;\n  const label = document.getElementById('raffle-label').value.trim();\n  const publish = document.getElementById('raffle-publish').checked;\n  const grade = document.getElementById('raffle-grade') ? document.getElementById('raffle-grade').value : '';\n  const section = document.getElementById('raffle-section') ? document.getElementById('raffle-section').value : '';\n\n  try{\n    const res = await api('/api/admin/raffle', {method:'POST', body: JSON.stringify({mode, grade, section, count, label, publish})});\n    document.getElementById('raffle-result').innerHTML = `\n      <div class=\"msg ok\">\ud83c\udf89 \u0646\u062a\u064a\u062c\u0629 \u0627\u0644\u0642\u0631\u0639\u0629</div>\n      ${res.winners.map(w=>`\n        <div class=\"student-row\">\n          <div>\n            <div class=\"name\">${w.name}</div>\n            <div class=\"sub\">${w.grade} / ${w.section}</div>\n          </div>\n          <div class=\"bal\">${w.balance}</div>\n        </div>`).join('')}\n    `;\n    if(publish) loadLeaderboard();\n  }catch(e){\n    showMsg('raffle-msg', e.message, 'err');\n  }\n}\n</script>\n</body>\n</html>\n";

